import { Product } from '../../products/entities/product.entity';
import { Cart } from './cart.entity';
@Entity({ name: 'cart_items' })
export class CartItem {
  @PrimaryGeneratedColumn()
  id: number;
  @Column()
  quantity: number;
  @Column({ type: 'decimal', precision: 10, scale: 2 })
  price: number; // Precio del producto en el momento de añadirlo
  @ManyToOne(() => Cart, (cart) => cart.items, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'cart_id' })
  cart: Cart;
  @ManyToOne(() => Product, { eager: true, onDelete: 'SET NULL' }) // eager para cargar producto automáticamente
  @JoinColumn({ name: 'product_id' })
  product: Product;
  @Column({ name: 'product_id' })
  productId: number;
}import {
  IsOptional,
  IsString,
  IsEmail,
  IsIn,
  IsNotEmpty,
  IsArray,
  ValidateNested,
  IsNumber,
  IsPositive,
} from 'class-validator';
import { Type } from 'class-transformer';
export class OrderItemDto {
  @IsNotEmpty({ message: 'El ID del producto es requerido' })
  @IsNumber({}, { message: 'El ID del producto debe ser un número' })
  productId: number;
  @IsNotEmpty({ message: 'La cantidad es requerida' })
  @IsNumber({}, { message: 'La cantidad debe ser un número' })
  @IsPositive({ message: 'La cantidad debe ser positiva' })
  quantity: number;
  @IsNotEmpty({ message: 'El precio es requerido' })
  @IsNumber({}, { message: 'El precio debe ser un número' })
  @IsPositive({ message: 'El precio debe ser positivo' })
  price: number;
}
export class CreateOrderDto {
  @IsNotEmpty({ message: 'El tipo de entrega es requerido' })
  @IsIn(['pickup', 'delivery'], {
    message: 'El tipo de entrega debe ser "pickup" o "delivery"',
  })
  deliveryType: 'pickup' | 'delivery';
  @IsOptional()
  @IsString()
  notes?: string;
  // Datos del cliente (requeridos para checkout invitado)
  @IsNotEmpty({ message: 'El nombre del cliente es requerido' })
  @IsString()
