  @IsNotEmpty({ message: 'El email del cliente es requerido' })
  @IsEmail({}, { message: 'El email debe ser válido' })
  customerEmail: string;
  @IsNotEmpty({ message: 'El teléfono del cliente es requerido' })
  @IsString()
