user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
    worker_connections 1024;
    use epoll;
    multi_accept on;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    # Logging
    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for"';
    access_log /var/log/nginx/access.log main;

    # Performance
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;
    keepalive_timeout 65;
    types_hash_max_size 2048;
    client_max_body_size 20M;

    # Gzip compression
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_types
        text/plain
        text/css
        text/xml
        text/javascript
        application/json
        application/javascript
        application/xml+rss
        application/atom+xml
        image/svg+xml;

    # Rate limiting
    limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;
    limit_req_zone $binary_remote_addr zone=web:10m rate=30r/s;

    # Upstream servers
    upstream api_backend {
        server api:3002;
        keepalive 32;
    }

    upstream web_backend {
        server web:3000;
        keepalive 32;
    }

    # Redirect HTTP to HTTPS
    server {
        listen 80;
        server_name _;
        return 301 https://$host$request_uri;
    }

    # Main server block
    server {
        listen 443 ssl http2;
        server_name yourdomain.com www.yourdomain.com;

        # SSL configuration
        ssl_certificate /etc/nginx/ssl/cert.pem;
        ssl_certificate_key /etc/nginx/ssl/key.pem;
        ssl_protocols TLSv1.2 TLSv1.3;
        ssl_ciphers ECDHE-RSA-AES256-GCM-SHA512:DHE-RSA-AES256-GCM-SHA512:ECDHE-RSA-AES256-GCM-SHA384:DHE-RSA-AES256-GCM-SHA384;
        ssl_prefer_server_ciphers off;
        ssl_session_cache shared:SSL:10m;
        ssl_session_timeout 10m;

        # Security headers
        add_header X-Frame-Options DENY always;
        add_header X-Content-Type-Options nosniff always;
        add_header X-XSS-Protection "1; mode=block" always;
        add_header Referrer-Policy "strict-origin-when-cross-origin" always;
        add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self' data:; connect-src 'self' https:; media-src 'self'; object-src 'none'; child-src 'none'; worker-src 'none'; frame-ancestors 'none'; form-action 'self'; base-uri 'self';" always;

        # API routes
        location /api/ {
            limit_req zone=api burst=20 nodelay;

            proxy_pass http://api_backend;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection 'upgrade';
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_cache_bypass $http_upgrade;

            # Timeouts
            proxy_connect_timeout 60s;
            proxy_send_timeout 60s;
            proxy_read_timeout 60s;
        }

        # Static files caching
        location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
            expires 1y;
            add_header Cache-Control "public, immutable";
            add_header X-Content-Type-Options nosniff;

            proxy_pass http://web_backend;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection 'upgrade';
            proxy_set_header Host $host;
            proxy_cache_bypass $http_upgrade;
        }

        # Next.js app
        location / {
            limit_req zone=web burst=50 nodelay;

            proxy_pass http://web_backend;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection 'upgrade';
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_cache_bypass $http_upgrade;

            # Timeouts
            proxy_connect_timeout 60s;
            proxy_send_timeout 60s;
            proxy_read_timeout 60s;
        }

        # Health check endpoint
        location /health {
            access_log off;
            return 200 "healthy\n";
            add_header Content-Type text/plain;
        }
    }
}"use client";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import RequireAdmin from "../../../components/auth/requireAdmin";
import CategoryTable from "../../../components/admin/CategoryTable";
import CategoryForm from "../../../components/admin/CategoryForm";
import {
    getCategories,
    createCategory,
    updateCategory,
    deleteCategory,
    type Category,
} from "../../../lib/categoriesApi";
function CategoriesPageContent() {
    const router = useRouter();
    const [categories, setCategories] = useState<Category[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [selectedCategory, setSelectedCategory] = useState<Category | null>(
        null
    );
    const [notification, setNotification] = useState<{
        message: string;
        type: "success" | "error";
    } | null>(null);
    // Cargar categorías
    const loadCategories = async () => {
        try {
            setIsLoading(true);
            const data = await getCategories();
            setCategories(data);
        } catch (error: any) {
            showNotification(
                error.message || "Error al cargar categorías",
                "error"
            );
        } finally {
            setIsLoading(false);
        }
    };
    useEffect(() => {
        loadCategories();
    }, []);
    // Mostrar notificación
    const showNotification = (message: string, type: "success" | "error") => {
        setNotification({ message, type });
        setTimeout(() => setNotification(null), 3000);
    };
    // Abrir formulario para crear
    const handleCreate = () => {
        setSelectedCategory(null);
        setIsFormOpen(true);
    };
    // Abrir formulario para editar
    const handleEdit = (category: Category) => {
        setSelectedCategory(category);
        setIsFormOpen(true);
    };
    // Guardar categoría (crear o actualizar)
    const handleSave = async (name: string) => {
        try {
            if (selectedCategory) {
                // Actualizar
                await updateCategory(selectedCategory.id, { name });
                showNotification("Categoría actualizada correctamente", "success");
            } else {
                // Crear
                await createCategory({ name });
                showNotification("Categoría creada correctamente", "success");
            }
            setIsFormOpen(false);
            setSelectedCategory(null);
            await loadCategories();
        } catch (error: any) {
            throw error; // El formulario manejará el error
        }
    };
    // Eliminar categoría
    const handleDelete = async (category: Category) => {
        try {
            await deleteCategory(category.id);
            showNotification("Categoría eliminada correctamente", "success");
            await loadCategories();
        } catch (error: any) {
            showNotification(
                error.message || "Error al eliminar categoría",
                "error"
            );
        }
    };
    // Cancelar formulario
    const handleCancel = () => {
        setIsFormOpen(false);
        setSelectedCategory(null);
    };
    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-semibold text-emerald-400">
                        Gestión de Categorías
                    </h1>
                    <p className="text-sm text-slate-400 mt-1">
                        Administra las categorías de productos
                    </p>
                </div>
                <button
                    onClick={handleCreate}
                    className="
            px-4 py-2 rounded-lg bg-emerald-600
            text-sm font-semibold text-white
            hover:bg-emerald-500 hover:shadow-md
            transition
          "
                >
                    + Nueva Categoría
                </button>
            </div>
            {/* Notificación */}
            {notification && (
                <div
                    className={`
            rounded-lg px-4 py-3 text-sm font-medium
            ${notification.type === "success"
                            ? "bg-emerald-50 text-emerald-700 border border-emerald-200"
                            : "bg-rose-50 text-rose-700 border border-rose-200"
                        }
          `}
                >
                    {notification.message}
                </div>
            )}
            {/* Tabla de categorías */}
            <CategoryTable
                categories={categories}
                onEdit={handleEdit}
                onDelete={handleDelete}
                isLoading={isLoading}
            />
            {/* Formulario modal */}
            <CategoryForm
                category={selectedCategory}
                onSave={handleSave}
                onCancel={handleCancel}
                isOpen={isFormOpen}
            />
        </div>
    );
}
export default function CategoriesPage() {
    return (
        <RequireAdmin>
            <CategoriesPageContent />
        </RequireAdmin>
    );
}// web/app/admin/customers/page.tsx
"use client";
import { useEffect, useMemo, useState } from "react";
import { getAllUsers } from "../../../lib/usersApi";
import { getAllOrders } from "../../../lib/ordersApi";
const currencyCLP = new Intl.NumberFormat("es-CL", {
    style: "currency",
    currency: "CLP",
    maximumFractionDigits: 0,
});
type CustomerData = {
    id: string;
    name: string;
    email: string;
    phone?: string;
    createdAt: string;
    ordersCount: number;
    totalSpent: number;
    type: "user" | "guest";
};
export default function AdminCustomersPage() {
    const [customers, setCustomers] = useState<CustomerData[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");
    const [search, setSearch] = useState("");
    // ──────────────── CARGA INICIAL ────────────────
    useEffect(() => {
        loadCustomers();
    }, []);
    const loadCustomers = async () => {
        try {
            setLoading(true);
            setError("");
            // Obtener usuarios registrados y órdenes
            const [users, orders] = await Promise.all([
                getAllUsers(),
                getAllOrders(),
            ]);
            // Crear mapa de clientes con sus estadísticas
            const customerMap = new Map<string, CustomerData>();
            // Agregar usuarios registrados
            users.forEach((user) => {
                customerMap.set(user.email, {
                    id: `USER-${user.id}`,
                    name: user.email.split("@")[0], // Usar parte del email como nombre
                    email: user.email,
                    phone: undefined,
                    createdAt: new Date().toISOString(), // Fecha actual por defecto
                    ordersCount: 0,
                    totalSpent: 0,
                    type: "user",
                });
            });
            // Procesar órdenes para calcular estadísticas
            orders.forEach((order: any) => {
                const email = order.user?.email || order.customerEmail;
                if (!email) return;
                const existing = customerMap.get(email);
                if (existing) {
                    // Cliente ya existe (usuario registrado o invitado)
                    existing.ordersCount += 1;
                    existing.totalSpent += Number(order.total);
                    // Actualizar fecha con la orden más antigua
                    if (order.createdAt && new Date(order.createdAt) < new Date(existing.createdAt)) {
                        existing.createdAt = order.createdAt;
                    }
                    // Actualizar nombre y teléfono si no existen
                    if (!existing.name || existing.name === email.split("@")[0]) {
                        existing.name = order.customerName || existing.name;
                    }
                    if (!existing.phone && order.customerPhone) {
                        existing.phone = order.customerPhone;
                    }
                } else {
                    // Cliente invitado (no tiene cuenta)
                    customerMap.set(email, {
                        id: `GUEST-${email}`,
                        name: order.customerName || email.split("@")[0],
                        email: email,
                        phone: order.customerPhone,
                        createdAt: order.createdAt,
                        ordersCount: 1,
                        totalSpent: Number(order.total),
                        type: "guest" as const,
                    });
                }
            });
            const customersArray = Array.from(customerMap.values());
            setCustomers(customersArray);
        } catch (err: any) {
            console.error("Error cargando clientes:", err);
            setError(err.message || "Error al cargar clientes");
        } finally {
            setLoading(false);
        }
    };
    const filteredCustomers = useMemo(() => {
        const text = search.trim().toLowerCase();
        return customers
            .slice()
            .sort(
                (a, b) =>
                    new Date(b.createdAt || "").getTime() -
                    new Date(a.createdAt || "").getTime()
            )
            .filter((c) => {
                if (!text) return true;
                return (
                    c.name.toLowerCase().includes(text) ||
                    c.email.toLowerCase().includes(text) ||
                    (c.phone ?? "").toLowerCase().includes(text)
                );
            });
    }, [customers, search]);
    const totalCustomers = customers.length;
    const totalOrders = customers.reduce(
        (acc, c) => acc + (c.ordersCount ?? 0),
        0
    );
    const totalRevenue = customers.reduce(
        (acc, c) => acc + (c.totalSpent ?? 0),
        0
    );
    if (loading) {
        return (
            <p className="text-base text-muted-foreground">
                Cargando clientes…
            </p>
        );
    }
    if (error) {
        return (
            <section className="space-y-6">
                <h2 className="text-2xl font-semibold">Clientes</h2>
                <div className="rounded-2xl border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-700">
                    {error}
                </div>
                <button
                    onClick={loadCustomers}
                    className="rounded-2xl bg-emerald-600 px-6 py-2.5 text-base font-semibold text-white hover:bg-emerald-500"
                >
                    Reintentar
                </button>
            </section>
        );
    }
    return (
        <section className="space-y-6">
            {/* Encabezado con métricas */}
            <div className="space-y-4">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                    <div>
                        <h2 className="text-2xl font-semibold tracking-tight">
                            Clientes
                        </h2>
                        <p className="text-base text-foreground">
                            Registro de clientes que han comprado o creado cuenta.
                        </p>
                    </div>
                    <button
                        onClick={loadCustomers}
                        className="rounded-2xl border border-border px-4 py-2 text-sm hover:bg-muted"
                    >
                        Actualizar
                    </button>
                </div>
                <div className="grid gap-4 md:grid-cols-3">
                    <div className="rounded-3xl border border-border bg-card px-5 py-4 text-card-foreground shadow-sm">
                        <p className="text-sm font-medium text-muted-foreground">
                            Clientes registrados
                        </p>
                        <p className="mt-2 text-3xl font-semibold">
                            {totalCustomers}
                        </p>
                    </div>
                    <div className="rounded-3xl border border-border bg-card px-5 py-4 text-card-foreground shadow-sm">
                        <p className="text-sm font-medium text-muted-foreground">
                            Órdenes asociadas
                        </p>
                        <p className="mt-2 text-3xl font-semibold">
                            {totalOrders}
                        </p>
                    </div>
                    <div className="rounded-3xl border border-border bg-card px-5 py-4 text-card-foreground shadow-sm">
                        <p className="text-sm font-medium text-muted-foreground">
                            Total en compras
                        </p>
                        <p className="mt-2 text-3xl font-semibold">
                            {currencyCLP.format(totalRevenue)}
                        </p>
                    </div>
                </div>
            </div>
            {/* Filtro de búsqueda */}
            <div className="flex flex-wrap gap-3 text-base">
                <input
                    placeholder="Buscar por nombre, correo o teléfono…"
                    className="min-w-[260px] flex-1 rounded-full border border-border bg-background px-4 py-2.5 text-base outline-none focus:border-emerald-500"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>
            {/* Tabla de clientes */}
            {filteredCustomers.length === 0 ? (
                <p className="text-base text-muted-foreground">
                    No hay clientes que coincidan con la búsqueda.
                </p>
            ) : (
                <div className="overflow-x-auto rounded-3xl border border-border bg-card shadow-sm">
                    <table className="min-w-full text-left text-base">
                        <thead className="bg-secondary/60 text-xs uppercase text-muted-foreground">
                            <tr>
                                <th className="px-5 py-3">Nombre</th>
                                <th className="px-5 py-3">Contacto</th>
                                <th className="px-5 py-3 hidden md:table-cell">Tipo</th>
                                <th className="px-5 py-3 hidden md:table-cell">
                                    Registrado
                                </th>
                                <th className="px-5 py-3">Órdenes</th>
                                <th className="px-5 py-3">Total gastado</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredCustomers.map((c) => (
                                <tr
                                    key={c.id}
                                    className="border-t border-border/70 hover:bg-muted/60"
                                >
                                    <td className="px-5 py-3">
                                        <div className="flex flex-col">
                                            <span className="font-medium text-foreground">
                                                {c.name}
                                            </span>
                                            <span className="text-sm text-muted-foreground">
                                                ID: {c.id}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-5 py-3">
                                        <div className="flex flex-col">
                                            <span className="text-sm text-foreground">
                                                {c.email}
                                            </span>
                                            <span className="text-sm text-muted-foreground">
                                                {c.phone || "Sin teléfono"}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-5 py-3 hidden md:table-cell">
                                        <span
                                            className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${c.type === "user"
                                                ? "bg-emerald-100 text-emerald-800"
                                                : "bg-blue-100 text-blue-800"
                                                }`}
                                        >
                                            {c.type === "user" ? "Usuario" : "Invitado"}
                                        </span>
                                    </td>
                                    <td className="px-5 py-3 hidden md:table-cell text-sm text-muted-foreground">
                                        {c.createdAt
                                            ? new Date(c.createdAt).toLocaleDateString(
                                                "es-CL"
                                            )
                                            : "Sin fecha"}
                                    </td>
                                    <td className="px-5 py-3">
                                        <span className="text-base font-semibold">
                                            {c.ordersCount ?? 0}
                                        </span>
                                    </td>
                                    <td className="px-5 py-3">
                                        <span className="text-base font-semibold">
                                            {currencyCLP.format(c.totalSpent ?? 0)}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </section>
    );
}// web/app/admin/orders/page.tsx
"use client";
import { useEffect, useMemo, useState } from "react";
import { getAllOrders } from "../../../lib/ordersApi";
import { formatCLP } from "../../../lib/price";
// Tipo de orden del backend
type BackendOrder = {
    id: number;
    user?: {
        id: number;
        email: string;
    } | null;
    items: Array<{
        id: number;
        product: {
            id: number;
            name: string;
        };
        quantity: number;
        price: number;
    }>;
    status: string;
    total: number;
    customerName: string;
    customerEmail: string;
    customerPhone?: string;
    deliveryType?: string;
    customerAddress?: string;
    createdAt: string;
    updatedAt: string;
};
type OrderStatus = "pending" | "completed" | "cancelled";
export default function AdminOrdersPage() {
    const [orders, setOrders] = useState<BackendOrder[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<"all" | OrderStatus>("all");
    const [selectedOrder, setSelectedOrder] = useState<BackendOrder | null>(null);
    // Cargar órdenes desde el backend
    useEffect(() => {
        loadOrders();
    }, []);
    const loadOrders = async () => {
        try {
            setLoading(true);
            setError("");
            const data = await getAllOrders();
            setOrders(data as any);
        } catch (err: any) {
            console.error("Error cargando órdenes:", err);
            setError(err.message || "Error al cargar las órdenes");
        } finally {
            setLoading(false);
        }
    };
    // Filtros
    const filteredOrders = useMemo(() => {
        const text = search.trim().toLowerCase();
        return orders
            .slice()
            .sort(
                (a, b) =>
                    new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
            )
            .filter((order) => {
                const matchesStatus =
                    statusFilter === "all" || order.status === statusFilter;
                const matchesText =
                    !text ||
                    order.id.toString().includes(text) ||
                    order.customerName.toLowerCase().includes(text) ||
                    order.customerEmail.toLowerCase().includes(text);
                return matchesStatus && matchesText;
            });
    }, [orders, search, statusFilter]);
    const getStatusBadge = (status: string) => {
        switch (status) {
            case "pending":
                return {
                    label: "Pendiente",
                    className: "bg-amber-100 text-amber-800",
                };
            case "completed":
                return {
                    label: "Completada",
                    className: "bg-emerald-100 text-emerald-800",
                };
            case "cancelled":
                return {
                    label: "Cancelada",
                    className: "bg-neutral-200 text-neutral-800",
                };
            default:
                return {
                    label: status,
                    className: "bg-gray-100 text-gray-800",
                };
        }
    };
    if (loading) {
        return (
            <section className="space-y-6">
                <h2 className="text-2xl font-semibold">Órdenes</h2>
                <p className="text-base text-muted-foreground">Cargando órdenes...</p>
            </section>
        );
    }
    if (error) {
        return (
            <section className="space-y-6">
                <h2 className="text-2xl font-semibold">Órdenes</h2>
                <div className="rounded-2xl border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-700">
                    {error}
                </div>
                <button
                    onClick={loadOrders}
                    className="rounded-2xl bg-emerald-600 px-6 py-2.5 text-base font-semibold text-white hover:bg-emerald-500"
                >
                    Reintentar
                </button>
            </section>
        );
    }
    return (
        <section className="space-y-6">
            {/* Encabezado */}
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <div>
                    <h2 className="text-2xl font-semibold tracking-tight">Órdenes</h2>
                    <p className="text-base text-foreground">
                        Total: {orders.length} órdenes
                    </p>
                </div>
                <button
                    onClick={loadOrders}
                    className="rounded-2xl border border-border px-4 py-2 text-sm hover:bg-muted"
                >
                    Actualizar
                </button>
            </div>
            {/* Filtros */}
            <div className="flex flex-wrap gap-3 text-base">
                <input
                    placeholder="Buscar por N° de orden, nombre o correo…"
                    className="min-w-[260px] flex-1 rounded-full border border-border bg-background px-4 py-2.5 text-base outline-none focus:border-emerald-500"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
                <select
                    value={statusFilter}
                    onChange={(e) =>
                        setStatusFilter(e.target.value as typeof statusFilter)
                    }
                    className="rounded-full border border-border bg-background px-4 py-2.5 text-base outline-none focus:border-emerald-500"
                >
                    <option value="all">Todos los estados</option>
                    <option value="pending">Pendiente</option>
                    <option value="completed">Completada</option>
                    <option value="cancelled">Cancelada</option>
                </select>
            </div>
            {/* Tabla */}
            {filteredOrders.length === 0 ? (
                <p className="text-base text-muted-foreground">
                    No hay órdenes que coincidan con el filtro.
                </p>
            ) : (
                <div className="overflow-x-auto rounded-3xl border border-border bg-card shadow-sm">
                    <table className="min-w-full text-left text-base">
                        <thead className="bg-secondary/60 text-xs uppercase text-muted-foreground">
                            <tr>
                                <th className="px-5 py-3">N° Orden</th>
                                <th className="px-5 py-3">Cliente</th>
                                <th className="px-5 py-3 hidden md:table-cell">Tipo</th>
                                <th className="px-5 py-3">Total</th>
                                <th className="px-5 py-3">Estado</th>
                                <th className="px-5 py-3 hidden md:table-cell">Fecha</th>
                                <th className="px-5 py-3 text-right">Acciones</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredOrders.map((order) => {
                                const badge = getStatusBadge(order.status);
                                const isGuest = !order.user;
                                return (
                                    <tr
                                        key={order.id}
                                        className="border-t border-border/70 hover:bg-muted/60"
                                    >
                                        <td className="px-5 py-3 font-semibold">#{order.id}</td>
                                        <td className="px-5 py-3">
                                            <div className="flex flex-col">
                                                <span className="font-medium text-foreground">
                                                    {order.customerName}
                                                </span>
                                                <span className="text-sm text-muted-foreground">
                                                    {order.customerEmail}
                                                </span>
                                            </div>
                                        </td>
                                        <td className="px-5 py-3 hidden md:table-cell">
                                            <span
                                                className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${isGuest
                                                        ? "bg-blue-100 text-blue-800"
                                                        : "bg-emerald-100 text-emerald-800"
                                                    }`}
                                            >
                                                {isGuest ? "Invitado" : "Usuario"}
                                            </span>
                                        </td>
                                        <td className="px-5 py-3 font-semibold">
                                            {formatCLP(order.total)}
                                        </td>
                                        <td className="px-5 py-3">
                                            <span
                                                className={`inline-flex items-center rounded-full px-3 py-1 text-xs font-semibold ${badge.className}`}
                                            >
                                                {badge.label}
                                            </span>
                                        </td>
                                        <td className="px-5 py-3 hidden md:table-cell text-sm text-muted-foreground">
                                            {new Date(order.createdAt).toLocaleString("es-CL", {
                                                dateStyle: "short",
                                                timeStyle: "short",
                                            })}
                                        </td>
                                        <td className="px-5 py-3 text-right">
                                            <button
                                                onClick={() => setSelectedOrder(order)}
                                                className="rounded-full border border-border px-4 py-1.5 text-sm hover:border-emerald-500 hover:text-emerald-700"
                                            >
                                                Ver detalle
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            )}
            {/* Modal detalle de orden */}
            {selectedOrder && (
                <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/40 px-4">
                    <div className="w-full max-w-3xl rounded-3xl border border-border bg-background p-6 shadow-xl max-h-[90vh] overflow-y-auto">
                        <div className="mb-4 flex items-center justify-between">
                            <h3 className="text-xl font-semibold">
                                Detalle orden #{selectedOrder.id}
                            </h3>
                            <button
                                onClick={() => setSelectedOrder(null)}
                                className="rounded-full border border-border px-3 py-1 text-sm hover:bg-muted"
                            >
                                Cerrar
                            </button>
                        </div>
                        <div className="mb-4 space-y-1 text-base">
                            <p>
                                <span className="font-medium">Cliente:</span>{" "}
                                {selectedOrder.customerName}
                            </p>
                            <p>
                                <span className="font-medium">Correo:</span>{" "}
                                {selectedOrder.customerEmail}
                            </p>
                            <p>
                                <span className="font-medium">Teléfono:</span>{" "}
                                {selectedOrder.customerPhone || "Sin teléfono"}
                            </p>
                            <p>
                                <span className="font-medium">Tipo:</span>{" "}
                                {selectedOrder.user ? "Usuario registrado" : "Invitado"}
                            </p>
                            {selectedOrder.deliveryType && (
                                <p>
                                    <span className="font-medium">Entrega:</span>{" "}
                                    {selectedOrder.deliveryType === "delivery"
                                        ? "A domicilio"
                                        : "Retiro en tienda"}
                                </p>
                            )}
                            {selectedOrder.customerAddress && (
                                <p>
                                    <span className="font-medium">Dirección:</span>{" "}
                                    {selectedOrder.customerAddress}
                                </p>
                            )}
                            <p>
                                <span className="font-medium">Fecha:</span>{" "}
                                {new Date(selectedOrder.createdAt).toLocaleString("es-CL", {
                                    dateStyle: "full",
                                    timeStyle: "short",
                                })}
                            </p>
                        </div>
                        <div className="mb-4 rounded-2xl border border-border bg-card">
                            <table className="min-w-full text-left text-base">
                                <thead className="bg-secondary/60 text-xs uppercase text-muted-foreground">
                                    <tr>
                                        <th className="px-4 py-2">Producto</th>
                                        <th className="px-4 py-2 text-center">Cantidad</th>
                                        <th className="px-4 py-2 text-right">Precio</th>
                                        <th className="px-4 py-2 text-right">Subtotal</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {selectedOrder.items.map((item) => (
                                        <tr
                                            key={item.id}
                                            className="border-t border-border/70"
                                        >
                                            <td className="px-4 py-2">{item.product.name}</td>
                                            <td className="px-4 py-2 text-center">
                                                {item.quantity}
                                            </td>
                                            <td className="px-4 py-2 text-right">
                                                {formatCLP(item.price)}
                                            </td>
                                            <td className="px-4 py-2 text-right">
                                                {formatCLP(item.price * item.quantity)}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="flex items-center justify-end gap-4 text-lg font-semibold">
                            <span>Total:</span>
                            <span>{formatCLP(selectedOrder.total)}</span>
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}// web/app/admin/products/page.tsx
"use client";
import { useEffect, useState, useMemo, useCallback, useRef } from "react";
import RequireAdmin from "../../../components/auth/requireAdmin";
import ProductForm from "../../../components/admin/ProductForm";
import type { Product } from "../../../lib/types";
import {
  getProducts,
  createProduct,
  updateProduct,
  deleteProduct,
  type CreateProductDto,
} from "../../../lib/productsApi";
import { getCategories, type Category } from "../../../lib/categoriesApi";
import { useToast } from "../../../components/ui/useToast";
function AdminProductsPageContent() {
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [categoryFilter, setCategoryFilter] = useState<string>("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const { toast, showToast } = useToast();
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);
  const ITEMS_PER_PAGE = 10;
  // Debounce para la búsqueda (300ms)
  useEffect(() => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }
    debounceTimerRef.current = setTimeout(() => {
      setDebouncedSearch(search);
    }, 300);
    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }
    };
  }, [search]);
  // Cargar datos
  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const [productsData, categoriesData] = await Promise.all([
        getProducts({ search: debouncedSearch, category: categoryFilter }),
        getCategories(),
      ]);
      setProducts(productsData);
      setCategories(categoriesData);
    } catch (err) {
      console.error("Error cargando datos:", err);
      showToast("Error al cargar datos", "error");
    } finally {
      setLoading(false);
    }
  }, [debouncedSearch, categoryFilter]);
  useEffect(() => {
    loadData();
  }, [loadData]);
  // Paginación
  const totalPages = Math.ceil(products.length / ITEMS_PER_PAGE);
  const paginatedProducts = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return products.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [products, currentPage]);
  // Resetear página cuando cambian los filtros
  useEffect(() => {
    setCurrentPage(1);
  }, [debouncedSearch, categoryFilter]);
  // Abrir formulario para crear
  const handleCreate = () => {
    setSelectedProduct(null);
    setIsFormOpen(true);
  };
  // Abrir formulario para editar
  const handleEdit = (product: Product) => {
    setSelectedProduct(product);
    setIsFormOpen(true);
  };
  // Guardar producto (crear o actualizar)
  const handleSave = async (data: CreateProductDto) => {
    try {
      if (selectedProduct) {
        // Actualizar
        await updateProduct(selectedProduct.id, data);
        showToast("Producto actualizado correctamente", "success");
      } else {
        // Crear
        await createProduct(data);
        showToast("Producto creado correctamente", "success");
      }
      setIsFormOpen(false);
      setSelectedProduct(null);
      await loadData();
    } catch (error: any) {
      showToast(error.message || "Error al guardar producto", "error");
      throw error;
    }
  };
  // Eliminar producto
  const handleDelete = async (product: Product) => {
    try {
      await deleteProduct(product.id);
      showToast("Producto eliminado correctamente", "success");
      await loadData();
    } catch (error: any) {
      showToast(error.message || "Error al eliminar producto", "error");
    }
  };
  // Cancelar formulario
  const handleCancel = () => {
    setIsFormOpen(false);
    setSelectedProduct(null);
  };
  if (loading) {
    return (
      <div className="text-center py-12">
        <p className="text-slate-400">Cargando productos...</p>
      </div>
    );
  }
  return (
    <section className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold text-emerald-400">
            Gestión de Productos
          </h1>
          <p className="text-sm text-slate-400 mt-1">
            {products.length} producto{products.length !== 1 ? "s" : ""}{" "}
            encontrado{products.length !== 1 ? "s" : ""}
          </p>
        </div>
        <button
          onClick={handleCreate}
          className="
            px-4 py-2 rounded-lg bg-emerald-600
            text-sm font-semibold text-white
            hover:bg-emerald-500 hover:shadow-md
            transition
          "
        >
          + Nuevo Producto
        </button>
      </div>
      {/* Notificación Toast */}
      {toast && (
        <div
          className={`
            rounded-lg px-4 py-3 text-sm font-medium
            ${toast.type === "success"
              ? "bg-emerald-50 text-emerald-700 border border-emerald-200"
              : toast.type === "error"
                ? "bg-rose-50 text-rose-700 border border-rose-200"
                : "bg-blue-50 text-blue-700 border border-blue-200"
            }
          `}
        >
          {toast.message}
        </div>
      )}
      {/* Filtros */}
      <div className="flex flex-col sm:flex-row gap-3">
        <input
          type="text"
          placeholder="Buscar por nombre, slug o categoría..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="
            flex-1 rounded-lg border border-slate-300 bg-white
            px-4 py-2 text-sm text-slate-800
            placeholder:text-slate-400
            focus:border-emerald-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/20
          "
        />
        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          className="
            rounded-lg border border-slate-300 bg-white
            px-4 py-2 text-sm text-slate-800
            focus:border-emerald-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/20
          "
        >
          <option value="all">Todas las categorías</option>
          {categories.map((cat) => (
            <option key={cat.id} value={cat.slug}>
              {cat.name}
            </option>
          ))}
        </select>
      </div>
      {/* Tabla */}
      {paginatedProducts.length === 0 ? (
        <div className="text-center py-12 bg-slate-50 rounded-lg border border-slate-200">
          <p className="text-slate-500">
            No hay productos que coincidan con el filtro.
          </p>
        </div>
      ) : (
        <>
          <div className="overflow-x-auto rounded-lg border border-slate-200">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                    Producto
                  </th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                    Categoría
                  </th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                    Precio
                  </th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                    Stock
                  </th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                    Estado
                  </th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-slate-700 uppercase tracking-wider">
                    Acciones
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-slate-200">
                {paginatedProducts.map((product) => (
                  <tr key={product.id} className="hover:bg-slate-50 transition">
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-3">
                        {product.imageUrl && (
                          <img
                            src={product.imageUrl}
                            alt={product.name}
                            className="h-12 w-12 rounded object-cover"
                          />
                        )}
                        <div>
                          <p className="text-sm font-medium text-slate-800">
                            {product.name}
                          </p>
                          <p className="text-xs text-slate-500 font-mono">
                            {product.slug}
                          </p>
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3 text-sm text-slate-600">
                      {product.category ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                          {product.category.name}
                        </span>
                      ) : (
                        <span className="text-slate-400">Sin categoría</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-sm font-semibold text-slate-800">
                      ${product.price.toLocaleString("es-CL")}
                      {product.isOnSale && product.discountPercent && (
                        <span className="ml-2 text-xs text-emerald-600">
                          -{product.discountPercent}%
                        </span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-sm text-slate-600">
                      {product.stock !== undefined ? (
                        <span
                          className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${product.stock > 50
                            ? "bg-green-100 text-green-800"
                            : product.stock > 0
                              ? "bg-yellow-100 text-yellow-800"
                              : "bg-red-100 text-red-800"
                            }`}
                        >
                          {product.stock} unidades
                        </span>
                      ) : (
                        <span className="text-slate-400">N/A</span>
                      )}
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex gap-1">
                        {product.isFeatured && (
                          <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-purple-100 text-purple-800">
                            ⭐
                          </span>
                        )}
                        {product.isOnSale && (
                          <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-emerald-100 text-emerald-800">
                            🏷️
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-sm text-right space-x-2">
                      <button
                        onClick={() => handleEdit(product)}
                        className="
                          inline-flex items-center px-3 py-1.5 rounded-md
                          text-xs font-medium text-emerald-700 bg-emerald-50
                          hover:bg-emerald-100
                          transition
                        "
                      >
                        Editar
                      </button>
                      <button
                        onClick={() => handleDelete(product)}
                        className="
                          inline-flex items-center px-3 py-1.5 rounded-md
                          text-xs font-medium text-rose-700 bg-rose-50
                          hover:bg-rose-100
                          transition
                        "
                      >
                        Eliminar
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {/* Paginación */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between">
              <p className="text-sm text-slate-600">
                Mostrando {(currentPage - 1) * ITEMS_PER_PAGE + 1} a{" "}
                {Math.min(currentPage * ITEMS_PER_PAGE, products.length)} de{" "}
                {products.length} productos
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="
                    px-3 py-1.5 rounded-md border border-slate-300
                    text-sm font-medium text-slate-700
                    hover:bg-slate-50
                    disabled:opacity-50 disabled:cursor-not-allowed
                    transition
                  "
                >
                  Anterior
                </button>
                <div className="flex gap-1">
                  {Array.from({ length: totalPages }, (_, i) => i + 1).map(
                    (page) => (
                      <button
                        key={page}
                        onClick={() => setCurrentPage(page)}
                        className={`
                          px-3 py-1.5 rounded-md text-sm font-medium
                          transition
                          ${currentPage === page
                            ? "bg-emerald-600 text-white"
                            : "border border-slate-300 text-slate-700 hover:bg-slate-50"
                          }
                        `}
                      >
                        {page}
                      </button>
                    )
                  )}
                </div>
                <button
                  onClick={() =>
                    setCurrentPage((p) => Math.min(totalPages, p + 1))
                  }
                  disabled={currentPage === totalPages}
                  className="
                    px-3 py-1.5 rounded-md border border-slate-300
                    text-sm font-medium text-slate-700
                    hover:bg-slate-50
                    disabled:opacity-50 disabled:cursor-not-allowed
                    transition
                  "
                >
                  Siguiente
                </button>
              </div>
            </div>
          )}
        </>
      )}
      {/* Formulario modal */}
      <ProductForm
        open={isFormOpen}
        onClose={handleCancel}
        onSave={handleSave}
        product={selectedProduct}
        categories={categories}
      />
    </section>
  );
}
export default function AdminProductsPage() {
  return (
    <RequireAdmin>
      <AdminProductsPageContent />
    </RequireAdmin>
  );
