        if (search) result.search = search;
        if (categoryId) result.categoryId = categoryId;
        if (onlyFeatured) result.isFeatured = true;
        if (onlyOnSale) result.isOnSale = true;
        if (minPrice && !isNaN(Number(minPrice))) result.minPrice = Number(minPrice);
        if (maxPrice && !isNaN(Number(maxPrice))) result.maxPrice = Number(maxPrice);
        return result;
    }, [search, categoryId, onlyFeatured, onlyOnSale, minPrice, maxPrice]);
    // Initialize pagination hook
    const {
        items: products,
        isLoading,
        isLoadingMore,
        error,
        hasMore,
        totalCount,
        loadMore,
        reset,
        retry,
    } = usePagination(fetchPaginatedProducts, 20, filters);
    // Initialize infinite scroll hook
    const sentinelRef = useInfiniteScroll(loadMore, hasMore, isLoading || isLoadingMore);
    // Reset pagination when filters change
    useEffect(() => {
        reset(filters);
        // Load first page with new filters
        loadMore();
    }, [search, categoryId, onlyFeatured, onlyOnSale, minPrice, maxPrice]);
    // Start performance monitoring in development
    useEffect(() => {
        if (process.env.NODE_ENV === 'development') {
            const stopMonitoring = startPerformanceMonitoring(30000); // Check every 30 seconds
            return stopMonitoring;
        }
    }, []);
    // Calculate max price for slider (fallback to reasonable default)
    const globalMaxPrice = 10000; // We'll use a reasonable default since we don't have all products
    // Get featured products for carousel (first 4 featured or first 4 products)
    const featuredProducts = useMemo(() => {
        const featured = products.filter((p: Product) => p.isFeatured);
        return featured.length > 0 ? featured.slice(0, 4) : products.slice(0, 4);
    }, [products]);
    // Handle form submission for filters (memoized for performance)
    const handleFilterSubmit = useCallback((event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        const formData = new FormData(event.currentTarget);
        const params = new URLSearchParams();
        const searchValue = formData.get('q') as string;
        const categoryValue = formData.get('cat') as string;
        const featuredValue = formData.get('featured') as string;
        const onSaleValue = formData.get('onSale') as string;
        const minPriceValue = formData.get('minPrice') as string;
        const maxPriceValue = formData.get('maxPrice') as string;
        if (searchValue) params.set('q', searchValue);
        if (categoryValue) params.set('cat', categoryValue);
        if (featuredValue) params.set('featured', '1');
        if (onSaleValue) params.set('onSale', '1');
        if (minPriceValue) params.set('minPrice', minPriceValue);
        if (maxPriceValue) params.set('maxPrice', maxPriceValue);
        router.push(`/catalogo?${params.toString()}`);
    }, [router]);
    // Handle clear filters (memoized for performance)
    const handleClearFilters = useCallback(() => {
        router.push('/catalogo');
    }, [router]);
    return (
        <section className="mx-auto max-w-7xl px-4 py-6 space-y-6">
            {/* Encabezado */}
            <header className="space-y-2">
                <h1 className="text-3xl font-semibold text-foreground">Catálogo</h1>
                <p className="text-base text-foreground">
                    Explora nuestra selección de productos de limpieza.
                </p>
            </header>
            <div className="mt-2 flex flex-col gap-6 md:flex-row">
                {/* SIDEBAR */}
                <aside
                    className="
            hidden md:block
            w-64
            rounded-3xl border border-emerald-200 bg-emerald-50
            p-5 space-y-6 text-sm shadow-md text-emerald-900
            sticky top-24
            max-h-[90vh]
            overflow-y-auto
          "
                >
                    <div className="space-y-1">
                        <p className="text-xs font-semibold uppercase tracking-wide text-emerald-800">
                            Filtros
                        </p>
                        <p className="text-xs">
                            Ajusta los filtros para encontrar el producto ideal.
                        </p>
                    </div>
                    <form onSubmit={handleFilterSubmit} className="space-y-5">
                        {/* BUSCAR */}
                        <div className="space-y-2">
                            <p className="text-xs font-semibold text-emerald-800">Buscar</p>
                            <input
                                type="text"
                                name="q"
                                defaultValue={search}
                                placeholder="Ej: cloro..."
                                className="
                  w-full rounded-full border border-emerald-200 bg-white 
                  px-3 py-2 text-sm 
                  placeholder:text-emerald-600
                  outline-none focus:border-emerald-500
                "
                            />
                        </div>
                        <hr className="border-emerald-200" />
                        {/* CATEGORÍAS DINÁMICAS */}
                        <div className="space-y-2">
                            <p className="text-xs font-semibold text-emerald-800">Categoría</p>
                            <div className="flex flex-col gap-2 text-sm">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input
                                        type="radio"
                                        name="cat"
                                        value=""
                                        defaultChecked={!categorySlug}
                                        className="h-4 w-4 text-emerald-600"
                                    />
                                    Todos
                                </label>
                                {categories.map((cat: Category) => (
                                    <label key={cat.id} className="flex items-center gap-2 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="cat"
                                            value={cat.slug}
                                            defaultChecked={categorySlug === cat.slug}
                                            className="h-4 w-4 text-emerald-600"
                                        />
                                        {cat.name}
                                    </label>
                                ))}
                            </div>
                        </div>
                        <hr className="border-emerald-200" />
                        {/* TIPO */}
                        <div className="space-y-2">
                            <p className="text-xs font-semibold text-emerald-800">Tipo de producto</p>
                            <label className="flex items-center gap-2 cursor-pointer">
                                <input
                                    type="checkbox"
                                    name="featured"
                                    value="1"
                                    defaultChecked={onlyFeatured}
                                    className="h-4 w-4 text-emerald-600"
                                />
                                Solo destacados
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer">
                                <input
                                    type="checkbox"
                                    name="onSale"
                                    value="1"
                                    defaultChecked={onlyOnSale}
                                    className="h-4 w-4 text-emerald-600"
                                />
                                Solo en oferta
                            </label>
                        </div>
                        <hr className="border-emerald-200" />
                        {/* PRECIO */}
                        <PriceRangeFilter
                            maxLimit={globalMaxPrice}
                            initialMaxPrice={maxPrice ? Number(maxPrice) : undefined}
                        />
                        <div className="flex items-center justify-between pt-2">
                            <button
                                type="submit"
                                className="
                  rounded-full bg-emerald-600
                  px-4 py-2 text-xs font-semibold text-white
                  hover:bg-emerald-500 transition
                "
                            >
                                Aplicar filtros
                            </button>
                            <button
                                type="button"
                                onClick={handleClearFilters}
                                className="text-xs text-emerald-700 hover:text-emerald-900"
                            >
                                Limpiar
                            </button>
                        </div>
                    </form>
                </aside>
                {/* CONTENIDO PRINCIPAL */}
                <div className="flex-1 space-y-6">
                    {/* Status message */}
                    {!isLoading || products.length > 0 ? (
                        <p className="text-sm text-muted-foreground">
                            {totalCount === 0
                                ? "No se encontraron productos."
                                : `Mostrando ${products.length} de ${totalCount} producto${totalCount === 1 ? "" : "s"}`}
                        </p>
                    ) : null}
                    {/* Error handling */}
                    {error && (
                        <ErrorMessage
                            message={`Error al cargar productos: ${error}`}
                            onRetry={retry}
                        />
                    )}
                    {/* Initial loading state */}
                    {isLoading && products.length === 0 && !error && (
                        <div className="space-y-6">
                            <div className="flex items-center justify-center py-4">
                                <LoadingSpinner size="lg" className="text-emerald-600" />
                                <span className="ml-3 text-sm text-muted-foreground">
                                    Cargando productos...
                                </span>
                            </div>
                            <SkeletonLoader count={8} />
                        </div>
                    )}
                    {/* Content when products are loaded */}
                    {!isLoading || products.length > 0 ? (
                        <>
                            {/* Featured products carousel */}
                            {featuredProducts.length > 0 && (
                                <OffersCarousel
                                    products={featuredProducts}
                                    title="Ofertas y destacados"
                                    subtitle="Selección especial para ti"
                                />
                            )}
                            <div className="space-y-2">
                                <h2 className="text-xl font-semibold text-foreground">
                                    Productos disponibles
                                </h2>
                                {/* Products grid */}
                                {products.length > 0 ? (
                                    <ProductGrid products={products} />
                                ) : !isLoading && !error && (
                                    <div className="flex flex-col items-center justify-center py-12 text-center">
                                        <svg className="h-12 w-12 text-gray-400 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2M4 13h2m13-8V4a1 1 0 00-1-1H7a1 1 0 00-1 1v1m8 0V4.5" />
                                        </svg>
                                        <h3 className="text-lg font-medium text-gray-900 mb-2">
                                            No se encontraron productos
                                        </h3>
                                        <p className="text-gray-500 mb-4">
                                            Intenta ajustar los filtros o buscar con otros términos.
                                        </p>
                                        <button
                                            onClick={handleClearFilters}
                                            className="inline-flex items-center rounded-md bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-500"
                                        >
                                            Limpiar filtros
                                        </button>
                                    </div>
                                )}
                                {/* Infinite scroll sentinel and loading more indicator */}
                                {hasMore && products.length > 0 && (
                                    <div ref={sentinelRef} className="flex justify-center py-6">
                                        {isLoadingMore && (
                                            <div className="flex items-center space-x-2">
                                                <LoadingSpinner size="sm" className="text-emerald-600" />
                                                <span className="text-sm text-muted-foreground">
                                                    Cargando más productos...
                                                </span>
                                            </div>
                                        )}
                                    </div>
                                )}
                                {/* End of results message */}
                                {!hasMore && products.length > 0 && (
                                    <div className="flex justify-center py-6">
                                        <div className="text-center">
                                            <svg className="h-8 w-8 text-gray-400 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M5 13l4 4L19 7" />
                                            </svg>
                                            <p className="text-sm text-muted-foreground">
                                                Has visto todos los productos disponibles
                                            </p>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </>
                    ) : null}
                </div>
            </div>
            {/* Performance Dashboard (development only) */}
            {process.env.NODE_ENV === 'development' && (
                <PerformanceDashboard
                    isVisible={showPerformanceDashboard}
                    onToggle={() => setShowPerformanceDashboard(!showPerformanceDashboard)}
                />
            )}
        </section>
    );
}"use client";
import { useRef } from "react";
import PriceRangeFilter from "../../components/carousel/priceRangeFilter";
import type { Category } from "../../lib/categoriesApi";
type Props = {
  categories: Category[];
  initialSearch: string;
  categorySlug: string;
  onlyFeatured: boolean;
  onlyOnSale: boolean;
  maxPrice: number | undefined;
  globalMaxPrice: number;
};
export default function CatalogFilters({
  categories,
  initialSearch,
  categorySlug,
  onlyFeatured,
  onlyOnSale,
  maxPrice,
  globalMaxPrice,
}: Props) {
  const formRef = useRef<HTMLFormElement | null>(null);
  // 💡 Cada vez que cambia cualquier input del formulario,
  //    auto-enviamos el form (GET /catalogo?...)
  const handleChange = () => {
    formRef.current?.requestSubmit();
  };
  return (
    <form
      action="/catalogo"
      ref={formRef}
      className="space-y-5"
      onChange={handleChange}
    >
      {/* BUSCAR */}
      <div className="space-y-2">
        <p className="text-xs font-semibold text-emerald-800">Buscar</p>
        <input
          type="text"
          name="q"
          defaultValue={initialSearch}
          placeholder="Ej: cloro..."
          className="
            w-full rounded-full border border-emerald-200 bg-white 
            px-3 py-2 text-sm 
            placeholder:text-emerald-600
            outline-none focus:border-emerald-500
          "
        />
      </div>
      <hr className="border-emerald-200" />
      {/* CATEGORÍAS DINÁMICAS */}
      <div className="space-y-2">
        <p className="text-xs font-semibold text-emerald-800">Categoría</p>
        <div className="flex flex-col gap-2 text-sm">
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="radio"
              name="cat"
              value=""
              defaultChecked={!categorySlug}
              className="h-4 w-4 text-emerald-600"
            />
            Todos
          </label>
          {categories.map((cat) => (
            <label
              key={cat.id}
              className="flex items-center gap-2 cursor-pointer"
            >
              <input
                type="radio"
                name="cat"
                value={cat.slug}
                defaultChecked={categorySlug === cat.slug}
                className="h-4 w-4 text-emerald-600"
              />
              {cat.name}
            </label>
          ))}
        </div>
      </div>
      <hr className="border-emerald-200" />
      {/* TIPO */}
      <div className="space-y-2">
        <p className="text-xs font-semibold text-emerald-800">
          Tipo de producto
        </p>
        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            name="featured"
            value="1"
            defaultChecked={onlyFeatured}
            className="h-4 w-4 text-emerald-600"
          />
          Solo destacados
        </label>
        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            name="onSale"
            value="1"
            defaultChecked={onlyOnSale}
            className="h-4 w-4 text-emerald-600"
          />
          Solo en oferta
        </label>
      </div>
      <hr className="border-emerald-200" />
      {/* PRECIO (mantengo tu componente tal cual) */}
      <PriceRangeFilter maxLimit={globalMaxPrice} initialMaxPrice={maxPrice} />
      {/* Link para limpiar filtros */}
      <div className="flex items-center justify-end pt-2">
        <a
          href="/catalogo"
          className="text-xs text-emerald-700 hover:text-emerald-900"
        >
          Limpiar filtros
        </a>
      </div>
    </form>
  );
}// web/app/catalogo/page.tsx
import CatalogoClient from "./CatalogoClient";
import { getCategories } from "../../lib/categoriesApi";
import CatalogFilters from "../catalogo/catalogoFilters";
type CatalogoPageProps = {
  searchParams?: {
    q?: string;
    cat?: string;
    featured?: string;
    onSale?: string;
    minPrice?: string;
    maxPrice?: string;
  };
};
export default async function CatalogoPage({ searchParams }: CatalogoPageProps) {
  // Await searchParams (Next.js 15 requirement)
  const params = await searchParams;
  // Get categories server-side (they don't change often)
  const categories = await getCategories();
  return (
    <CatalogoClient
      initialSearchParams={params}
      categories={categories}
    />
  );
}// web/app/checkout/page.tsx
"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { useCart } from "../../components/cart/cartContext";
import { useAuth } from "../../contexts/AuthContext";
import { toNumber, formatCLP } from "../../lib/price";
import { createWebpayTransaction } from "../../lib/paymentsApi";
import { createCheckoutOrder } from "../../lib/ordersApi";
type DeliveryType = "pickup" | "delivery";
export default function CheckoutPage() {
  const router = useRouter();
  const { items, totalAmount, clear } = useCart();
  const { user, isAuthenticated } = useAuth();
  // Datos del cliente
  const [customerName, setCustomerName] = useState("");
  const [customerEmail, setCustomerEmail] = useState("");
  const [customerPhone, setCustomerPhone] = useState("");
  const [customerRut, setCustomerRut] = useState("");
  // Datos de entrega
  const [deliveryType, setDeliveryType] = useState<DeliveryType>("pickup");
  const [customerAddress, setCustomerAddress] = useState("");
  const [customerRegion, setCustomerRegion] = useState("");
  const [customerCommune, setCustomerCommune] = useState("");
  const [notes, setNotes] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  // Prellenar datos si el usuario está autenticado
  useEffect(() => {
    if (user) {
      setCustomerEmail(user.email || "");
    }
  }, [user]);
  // Si no hay productos en el carrito
  if (!items || items.length === 0) {
    return (
      <section className="mx-auto max-w-3xl px-4 py-8 space-y-4">
        <h1 className="text-2xl font-semibold text-foreground">
          No tienes productos en el carrito
        </h1>
        <p className="text-base text-muted-foreground">
          Agrega algunos productos antes de continuar al pago.
        </p>
        <Link
          href="/catalogo"
          className="inline-flex items-center justify-center rounded-2xl bg-emerald-600 px-6 py-2.5 text-base font-semibold text-white hover:bg-emerald-500"
        >
          Ir al catálogo
        </Link>
      </section>
    );
  }
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    // Validaciones
    if (!customerName.trim() || !customerEmail.trim() || !customerPhone.trim()) {
      setError("Por favor completa todos los campos requeridos del comprador.");
      return;
    }
    if (deliveryType === "delivery") {
      if (!customerAddress.trim() || !customerRegion.trim() || !customerCommune.trim()) {
        setError("Para envío a domicilio debes completar todos los datos de dirección.");
        return;
      }
    }
    setIsSubmitting(true);
    try {
      // Crear la orden en el backend
      const orderData = {
        deliveryType,
        notes: notes.trim() || undefined,
        customerName: customerName.trim(),
        customerEmail: customerEmail.trim(),
        customerPhone: customerPhone.trim(),
        customerRut: customerRut.trim() || undefined,
        customerAddress: deliveryType === "delivery" ? customerAddress.trim() : undefined,
        customerRegion: deliveryType === "delivery" ? customerRegion.trim() : undefined,
        customerCommune: deliveryType === "delivery" ? customerCommune.trim() : undefined,
      };
      const order = await createCheckoutOrder(orderData, items);
      // Crear la transacción de Webpay
      const webpayData = await createWebpayTransaction(order.id);
      // Vaciar carrito antes de redirigir
      await clear();
      // Redirigir a Webpay
      window.location.href = `${webpayData.url}?token_ws=${webpayData.token}`;
    } catch (err: any) {
      console.error("Error al procesar el pago:", err);
      setError(err.message || "Ocurrió un error al procesar tu pedido. Intenta nuevamente.");
      setIsSubmitting(false);
    }
  };
  return (
    <section className="mx-auto max-w-5xl px-4 py-8 space-y-6">
      <header className="space-y-1">
        <h1 className="text-3xl font-semibold text-foreground">
          Confirmar pedido
        </h1>
        <p className="text-base text-muted-foreground">
          Completa tus datos y elige el tipo de entrega para continuar al pago.
        </p>
      </header>
      {/* Aviso para invitados */}
      {!isAuthenticated && (
        <div className="rounded-2xl border border-blue-300 bg-blue-50 px-4 py-3 text-sm text-blue-800">
          Puedes comprar como invitado o{" "}
          <Link
            href="/auth/login"
            className="font-semibold text-emerald-700 hover:text-emerald-800"
          >
            iniciar sesión
          </Link>{" "}
          para guardar tu historial de pedidos.
        </div>
      )}
      {error && (
        <div className="rounded-2xl border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-700">
          {error}
        </div>
      )}
      <div className="grid gap-6 md:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)] items-start">
        {/* Columna izquierda: formulario */}
        <form
          onSubmit={handleSubmit}
          className="space-y-5 rounded-3xl border border-border bg-card p-6 shadow-sm"
        >
          {/* Datos del comprador */}
          <div className="space-y-3">
            <h2 className="text-lg font-semibold text-foreground">
              Datos del comprador
            </h2>
            <div className="space-y-1">
              <label className="block text-xs font-medium text-foreground">
                Nombre completo *
              </label>
              <input
                type="text"
                value={customerName}
                onChange={(e) => setCustomerName(e.target.value)}
                required
                className="w-full rounded-2xl border border-border bg-white px-3 py-2.5 text-base text-foreground placeholder:text-muted-foreground outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100"
                placeholder="Ej: Juan Pérez"
              />
            </div>
            <div className="grid gap-3 md:grid-cols-2">
              <div className="space-y-1">
                <label className="block text-xs font-medium text-foreground">
                  Email *
                </label>
                <input
                  type="email"
                  value={customerEmail}
                  onChange={(e) => setCustomerEmail(e.target.value)}
                  required
                  className="w-full rounded-2xl border border-border bg-white px-3 py-2.5 text-base text-foreground placeholder:text-muted-foreground outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100"
                  placeholder="correo@ejemplo.com"
                />
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-medium text-foreground">
                  Teléfono *
                </label>
                <input
                  type="tel"
                  value={customerPhone}
                  onChange={(e) => setCustomerPhone(e.target.value)}
                  required
                  className="w-full rounded-2xl border border-border bg-white px-3 py-2.5 text-base text-foreground placeholder:text-muted-foreground outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100"
                  placeholder="+56 9 1234 5678"
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="block text-xs font-medium text-foreground">
                RUT (opcional)
              </label>
              <input
                type="text"
                value={customerRut}
                onChange={(e) => setCustomerRut(e.target.value)}
                className="w-full rounded-2xl border border-border bg-white px-3 py-2.5 text-base text-foreground placeholder:text-muted-foreground outline-none focus:border-emerald-500 focus:ring-2 focus:ring-emerald-100"
                placeholder="12.345.678-9"
              />
            </div>
          </div>
          {/* Tipo de entrega */}
          <div className="space-y-3 pt-2">
            <h2 className="text-lg font-semibold text-foreground">
              Tipo de entrega
            </h2>
            <div className="space-y-3">
              <label className="flex items-start gap-3 rounded-2xl border border-border bg-white px-4 py-3 text-sm text-foreground cursor-pointer hover:border-emerald-500">
                <input
                  type="radio"
                  name="deliveryType"
                  value="pickup"
                  checked={deliveryType === "pickup"}
                  onChange={() => setDeliveryType("pickup")}
                  className="mt-[2px] h-4 w-4"
                />
                <div>
                  <p className="font-semibold">Retiro en tienda</p>
                  <p className="text-xs text-muted-foreground">
                    Coordinaremos el lugar y horario exacto una vez confirmada la orden.
                  </p>
                </div>
              </label>
              <label className="flex items-start gap-3 rounded-2xl border border-border bg-white px-4 py-3 text-sm text-foreground cursor-pointer hover:border-emerald-500">
                <input
                  type="radio"
                  name="deliveryType"
                  value="delivery"
                  checked={deliveryType === "delivery"}
