            });
            // Select second image
            fireEvent.click(imageContainers[1]);
            await waitFor(() => {
                const selectButton = screen.getByRole('button', { name: /select \(2\)/i });
                expect(selectButton).toBeTruthy();
            });
            // Select third image
            fireEvent.click(imageContainers[2]);
            await waitFor(() => {
                const selectButton = screen.getByRole('button', { name: /select \(3\)/i });
                expect(selectButton).toBeTruthy();
            });
        });
        it('should reset selection state when modal closes', async () => {
            const mockImages = ['https://example.com/image1.jpg'];
            vi.mocked(mediaApi.listImages).mockResolvedValue(mockImages);
            const mockOnSelect = vi.fn();
            const mockOnClose = vi.fn();
            const { container, rerender } = render(
                <MediaPicker
                    open={true}
                    multiple={true}
                    onSelect={mockOnSelect}
                    onClose={mockOnClose}
                />
            );
            // Wait for images to load
            await waitFor(() => {
                const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                expect(imageContainers.length).toBe(1);
            });
            // Select image
            const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
            fireEvent.click(imageContainers[0]);
            await waitFor(() => {
                const selectButton = screen.getByRole('button', { name: /select \(1\)/i });
                expect(selectButton).toBeTruthy();
            });
            // Close modal (get the footer Close button)
            const closeButtons = screen.getAllByRole('button', { name: /close/i });
            const footerCloseButton = closeButtons.find(btn => btn.textContent === 'Close');
            expect(footerCloseButton).toBeTruthy();
            fireEvent.click(footerCloseButton!);
            // Reopen modal
            rerender(
                <MediaPicker
                    open={true}
                    multiple={true}
                    onSelect={mockOnSelect}
                    onClose={mockOnClose}
                />
            );
            // Wait for modal to reopen
            await waitFor(() => {
                const modal = screen.getByRole('dialog');
                expect(modal).toBeTruthy();
            });
            // Selection should be reset (button disabled)
            const selectButton = screen.getByRole('button', { name: /select/i });
            expect(selectButton).toBeDisabled();
        });
    });
    describe('Image loading', () => {
        it('should fetch images when modal opens', async () => {
            const mockImages = ['https://example.com/image1.jpg'];
            vi.mocked(mediaApi.listImages).mockResolvedValue(mockImages);
            const mockOnSelect = vi.fn();
            const mockOnClose = vi.fn();
            render(
                <MediaPicker
                    open={true}
                    onSelect={mockOnSelect}
                    onClose={mockOnClose}
                />
            );
            // Wait for modal to render
            await waitFor(() => {
                const modal = screen.getByRole('dialog');
                expect(modal).toBeTruthy();
            });
            // Verify listImages was called
            expect(mediaApi.listImages).toHaveBeenCalledTimes(1);
        });
        it('should display loading state while fetching images', async () => {
            // Mock listImages with a delay
            vi.mocked(mediaApi.listImages).mockImplementation(async () => {
                await new Promise(resolve => setTimeout(resolve, 100));
                return [];
            });
            const mockOnSelect = vi.fn();
            const mockOnClose = vi.fn();
            const { container } = render(
                <MediaPicker
                    open={true}
                    onSelect={mockOnSelect}
                    onClose={mockOnClose}
                />
            );
            // Wait for modal to render
            await waitFor(() => {
                const modal = screen.getByRole('dialog');
                expect(modal).toBeTruthy();
            });
            // Should show loading skeletons
            const skeletons = container.querySelectorAll('.animate-pulse');
            expect(skeletons.length).toBeGreaterThan(0);
        });
        it('should display error message when image loading fails', async () => {
            vi.mocked(mediaApi.listImages).mockRejectedValue(new Error('Failed to load'));
            const mockOnSelect = vi.fn();
            const mockOnClose = vi.fn();
            render(
                <MediaPicker
                    open={true}
                    onSelect={mockOnSelect}
                    onClose={mockOnClose}
                />
            );
            // Wait for error to appear
            await waitFor(() => {
                const errorMessage = screen.queryByText(/failed to load/i);
                expect(errorMessage).toBeTruthy();
            }, { timeout: 1000 });
        });
    });
});'use client';
import { useState, useEffect, useCallback, useRef } from 'react';
import MediaUpload from './MediaUpload';
import MediaGallery from './MediaGallery';
import { listImages } from '@/lib/mediaApi';
/**
 * Props for MediaPicker component
 */
type MediaPickerProps = {
    open: boolean;
    multiple?: boolean;
    initialSelection?: string[];
    onSelect: (urls: string[]) => void;
    onClose: () => void;
};
/**
 * Tab type for the media picker
 */
type TabType = 'upload' | 'library';
/**
 * MediaPicker Component
 * Modal component for uploading and selecting images from media library
 */
export default function MediaPicker({
    open,
    multiple = false,
    initialSelection = [],
    onSelect,
    onClose,
}: MediaPickerProps) {
    const [activeTab, setActiveTab] = useState<TabType>('library');
    const [selectedUrls, setSelectedUrls] = useState<string[]>([]);
    const [images, setImages] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const modalRef = useRef<HTMLDivElement>(null);
    const previousFocusRef = useRef<HTMLElement | null>(null);
    /**
     * Load images from API
     */
    const loadImages = useCallback(async () => {
        try {
            setIsLoading(true);
            setError(null);
            const imageList = await listImages();
            setImages(imageList);
        } catch (err: any) {
            console.error('Error loading images:', err);
            setError(err.message || 'Failed to load images');
        } finally {
            setIsLoading(false);
        }
    }, []);
    /**
     * Load images when modal opens
     */
    useEffect(() => {
        if (open) {
            loadImages();
            // Set initial selection when modal opens
            setSelectedUrls(initialSelection);
        }
    }, [open, loadImages, initialSelection]);
    /**
     * Handle image uploaded
     * Adds new image to list, auto-selects it, and immediately adds to form
     */
    const handleImageUploaded = useCallback((url: string) => {
        setImages((prev) => [url, ...prev]);
        // Auto-select newly uploaded image
        setSelectedUrls((prev) => {
            const updated = [...prev, url];
            // Schedule onSelect to run after render completes
            setTimeout(() => {
                onSelect(updated);
            }, 0);
            return updated;
        });
        setActiveTab('library');
    }, [onSelect]);
    /**
     * Handle toggle selection
     * Manages single vs multiple selection modes
     */
    const handleToggleSelect = useCallback((url: string) => {
        setSelectedUrls((prev) => {
            if (multiple) {
                // Multiple selection mode: toggle the URL
                if (prev.includes(url)) {
                    return prev.filter((u) => u !== url);
                } else {
                    return [...prev, url];
                }
            } else {
                // Single selection mode: replace with new selection or deselect
                if (prev.includes(url)) {
                    return [];
                } else {
                    return [url];
                }
            }
        });
    }, [multiple]);
    /**
     * Handle confirm selection
     * Calls onSelect with selected URLs and closes modal
     */
    const handleConfirmSelection = useCallback(() => {
        onSelect(selectedUrls);
        setSelectedUrls([]);
        onClose();
    }, [selectedUrls, onSelect, onClose]);
    /**
     * Handle close
     * Resets state and closes modal
     */
    const handleClose = useCallback(() => {
        setSelectedUrls([]);
        setActiveTab('library');
        onClose();
    }, [onClose]);
    /**
     * Handle refresh
     * Reloads the image list
     */
    const handleRefresh = useCallback(() => {
        loadImages();
    }, [loadImages]);
    /**
     * Handle escape key and focus management
     */
    useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && open) {
                handleClose();
            }
        };
        if (open) {
            // Store the currently focused element
            previousFocusRef.current = document.activeElement as HTMLElement;
            document.addEventListener('keydown', handleEscape);
            // Prevent background scrolling
            document.body.style.overflow = 'hidden';
            // Focus the modal after a short delay to ensure it's rendered
            setTimeout(() => {
                modalRef.current?.focus();
            }, 100);
        } else {
            // Return focus to the previously focused element when closing
            if (previousFocusRef.current) {
                previousFocusRef.current.focus();
            }
        }
        return () => {
            document.removeEventListener('keydown', handleEscape);
            document.body.style.overflow = 'unset';
        };
    }, [open, handleClose]);
    /**
     * Focus trap implementation
     */
    useEffect(() => {
        if (!open || !modalRef.current) return;
        const handleTabKey = (e: KeyboardEvent) => {
            if (e.key !== 'Tab') return;
            const focusableElements = modalRef.current?.querySelectorAll(
                'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
            );
            if (!focusableElements || focusableElements.length === 0) return;
            const firstElement = focusableElements[0] as HTMLElement;
            const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement;
            if (e.shiftKey) {
                // Shift + Tab
                if (document.activeElement === firstElement) {
                    e.preventDefault();
                    lastElement.focus();
                }
            } else {
                // Tab
                if (document.activeElement === lastElement) {
                    e.preventDefault();
                    firstElement.focus();
                }
            }
        };
        document.addEventListener('keydown', handleTabKey);
        return () => {
            document.removeEventListener('keydown', handleTabKey);
        };
    }, [open]);
    // Don't render if not open
    if (!open) {
        return null;
    }
    return (
        <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
            onClick={handleClose}
            role="dialog"
            aria-modal="true"
            aria-labelledby="media-picker-title"
        >
            {/* Modal Container */}
            <div
                ref={modalRef}
                tabIndex={-1}
                className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-5xl max-h-[90vh] m-4 md:m-0 flex flex-col focus:outline-none"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
                    <h2
                        id="media-picker-title"
                        className="text-xl font-semibold text-gray-900 dark:text-white"
                    >
                        Media Picker
                    </h2>
                    <button
                        onClick={handleClose}
                        className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                        aria-label="Close modal"
                    >
                        <svg
                            className="w-6 h-6"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                        >
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M6 18L18 6M6 6l12 12"
                            />
                        </svg>
                    </button>
                </div>
                {/* Tabs */}
                <div className="flex border-b border-gray-200 dark:border-gray-700" role="tablist">
                    <button
                        onClick={() => setActiveTab('upload')}
                        role="tab"
                        aria-selected={activeTab === 'upload'}
                        aria-controls="upload-panel"
                        aria-label="Upload File tab"
                        tabIndex={activeTab === 'upload' ? 0 : -1}
                        className={`flex-1 md:flex-none px-4 md:px-6 py-3 font-medium text-sm md:text-base transition-colors focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500 ${activeTab === 'upload'
                            ? 'text-blue-600 border-b-2 border-blue-600'
                            : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white'
                            }`}
                    >
                        Upload File
                    </button>
                    <button
                        onClick={() => setActiveTab('library')}
                        role="tab"
                        aria-selected={activeTab === 'library'}
                        aria-controls="library-panel"
                        aria-label="Media Library tab"
                        tabIndex={activeTab === 'library' ? 0 : -1}
                        className={`flex-1 md:flex-none px-4 md:px-6 py-3 font-medium text-sm md:text-base transition-colors focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500 ${activeTab === 'library'
                            ? 'text-blue-600 border-b-2 border-blue-600'
                            : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white'
                            }`}
                    >
                        Media Library
                    </button>
                </div>
                {/* Content */}
                <div className="flex-1 overflow-hidden">
                    {activeTab === 'upload' ? (
                        <div
                            className="p-6"
                            role="tabpanel"
                            id="upload-panel"
                            aria-labelledby="upload-tab"
                        >
                            <MediaUpload onUploaded={handleImageUploaded} />
                        </div>
                    ) : (
                        <div
                            role="tabpanel"
                            id="library-panel"
                            aria-labelledby="library-tab"
                        >
                            <MediaGallery
                                images={images}
                                selected={selectedUrls}
                                onToggleSelect={handleToggleSelect}
                                onRefresh={handleRefresh}
                                isLoading={isLoading}
                            />
                        </div>
                    )}
                </div>
                {/* Error Message */}
                {error && (
                    <div className="px-6 py-3 bg-red-50 dark:bg-red-900/20 border-t border-red-200 dark:border-red-800">
                        <p className="text-sm text-red-700 dark:text-red-400">{error}</p>
                    </div>
                )}
                {/* Footer with Action Buttons */}
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-end gap-2 sm:gap-3 p-4 border-t border-gray-200 dark:border-gray-700">
                    <button
                        onClick={handleClose}
                        aria-label="Close media picker"
                        className="px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 order-2 sm:order-1"
                    >
                        Close
                    </button>
                    <button
                        onClick={handleConfirmSelection}
                        disabled={selectedUrls.length === 0}
                        aria-label={`Select ${selectedUrls.length} image${selectedUrls.length !== 1 ? 's' : ''}`}
                        className={`px-4 py-2 rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 order-1 sm:order-2 ${selectedUrls.length === 0
                            ? 'bg-gray-300 dark:bg-gray-700 text-gray-500 dark:text-gray-400 cursor-not-allowed'
                            : 'bg-blue-600 text-white hover:bg-blue-700'
                            }`}
                    >
                        Select {selectedUrls.length > 0 && `(${selectedUrls.length})`}
                    </button>
                </div>
            </div>
        </div>
    );
}/**
 * Property-Based Tests for MediaUpload Component
 * **Feature: media-picker, Property 2: Upload button state during upload**
 * **Validates: Requirements 1.2**
 * 
 * Property 2: Upload button state during upload
 * For any upload operation in progress, the upload button should be disabled 
 * and a loading indicator should be visible.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor, cleanup } from '@testing-library/react';
import * as fc from 'fast-check';
import MediaUpload from './MediaUpload';
import * as mediaApi from '@/lib/mediaApi';
// Mock the mediaApi module
vi.mock('@/lib/mediaApi', () => ({
    uploadImage: vi.fn(),
}));
describe('MediaUpload - Property-Based Tests', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });
    afterEach(() => {
        cleanup();
    });
    describe('Property 2: Upload button state during upload', () => {
        it('should disable upload button and show loading indicator during upload', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate random file type
                    fc.constantFrom('image/jpeg', 'image/png', 'image/webp', 'image/gif'),
                    async (fileType) => {
                        // Create a mock file
                        const mockFile = new File(
                            ['mock content'],
                            'test.jpg',
                            { type: fileType }
                        );
                        // Mock uploadImage to resolve after a short delay
                        vi.mocked(mediaApi.uploadImage).mockImplementation(async () => {
                            await new Promise(resolve => setTimeout(resolve, 50));
                            return { url: 'https://example.com/uploaded-image.jpg' };
                        });
                        const mockOnUploaded = vi.fn();
                        // Render component
                        const { container, unmount } = render(<MediaUpload onUploaded={mockOnUploaded} />);
                        try {
                            // Find file input and simulate file selection
                            const fileInput = container.querySelector('input[type="file"]') as HTMLInputElement;
                            expect(fileInput).toBeTruthy();
                            // Create a mock FileList
                            Object.defineProperty(fileInput, 'files', {
                                value: [mockFile],
                                writable: false,
                            });
                            // Trigger change event
                            fireEvent.change(fileInput);
                            // Wait for preview to be generated and button to be enabled
                            await waitFor(() => {
                                const preview = container.querySelector('img[alt*="Preview of test.jpg"]');
                                expect(preview).toBeTruthy();
                            }, { timeout: 500 });
                            // Get upload button by text
                            const uploadButton = screen.getByText(/upload image/i);
                            expect(uploadButton).toBeTruthy();
                            // Click upload button
                            fireEvent.click(uploadButton!);
                            // Check that button is disabled and shows loading state with spinner
                            await waitFor(() => {
                                const buttons = container.querySelectorAll('button');
                                const loadingButton = Array.from(buttons).find(btn =>
                                    btn.textContent?.includes('Uploading')
                                );
                                expect(loadingButton).toBeTruthy();
                                expect(loadingButton).toBeDisabled();
                                // Verify loading indicator is visible (spinner SVG)
                                const spinner = container.querySelector('.animate-spin');
                                expect(spinner).toBeTruthy();
                            }, { timeout: 300 });
                            // Wait for upload to complete
                            await waitFor(() => {
                                expect(mockOnUploaded).toHaveBeenCalled();
                            }, { timeout: 500 });
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
        it('should keep button disabled throughout entire upload process', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate random valid file type
                    fc.constantFrom('image/jpeg', 'image/png', 'image/webp', 'image/gif'),
                    async (fileType) => {
                        // Create a mock file
                        const mockFile = new File(['mock content'], 'test.jpg', { type: fileType });
                        // Track button state changes
                        const buttonStates: boolean[] = [];
                        // Mock uploadImage with delay
                        vi.mocked(mediaApi.uploadImage).mockImplementation(async () => {
                            // Simulate upload delay
                            await new Promise(resolve => setTimeout(resolve, 100));
                            return { url: 'https://example.com/test.jpg' };
                        });
                        const mockOnUploaded = vi.fn();
                        // Render component
                        const { container, unmount } = render(<MediaUpload onUploaded={mockOnUploaded} />);
                        try {
                            // Select file
                            const fileInput = container.querySelector('input[type="file"]') as HTMLInputElement;
                            Object.defineProperty(fileInput, 'files', {
                                value: [mockFile],
                                writable: false,
                            });
                            fireEvent.change(fileInput);
                            // Wait for preview
                            await waitFor(() => {
                                const preview = container.querySelector('img[alt*="Preview of test.jpg"]');
                                expect(preview).toBeTruthy();
                            }, { timeout: 500 });
                            // Click upload
                            const uploadButton = screen.getByText(/upload image/i);
                            fireEvent.click(uploadButton!);
                            // Sample button state multiple times during upload
                            for (let i = 0; i < 3; i++) {
                                await new Promise(resolve => setTimeout(resolve, 30));
                                const button = container.querySelector('button[disabled]');
                                buttonStates.push(button !== null);
                            }
                            // Wait for completion
                            await waitFor(() => {
                                expect(mockOnUploaded).toHaveBeenCalled();
                            }, { timeout: 500 });
                            // Verify button was disabled during all samples
                            expect(buttonStates.every(state => state === true)).toBe(true);
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
        it('should re-enable button after upload completes or fails', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate random outcome (success or failure)
                    fc.boolean(),
                    async (shouldSucceed) => {
                        const mockFile = new File(['mock content'], 'test.jpg', { type: 'image/jpeg' });
                        // Mock uploadImage to succeed or fail
                        if (shouldSucceed) {
                            vi.mocked(mediaApi.uploadImage).mockResolvedValue({
                                url: 'https://example.com/test.jpg',
                            });
                        } else {
                            vi.mocked(mediaApi.uploadImage).mockRejectedValue(
                                new Error('Upload failed')
                            );
                        }
                        const mockOnUploaded = vi.fn();
                        // Render component
                        const { container, unmount } = render(<MediaUpload onUploaded={mockOnUploaded} />);
                        try {
                            // Select file
                            const fileInput = container.querySelector('input[type="file"]') as HTMLInputElement;
                            Object.defineProperty(fileInput, 'files', {
                                value: [mockFile],
                                writable: false,
                            });
                            fireEvent.change(fileInput);
                            // Wait for preview
                            await waitFor(() => {
                                const preview = container.querySelector('img[alt*="Preview of test.jpg"]');
                                expect(preview).toBeTruthy();
                            }, { timeout: 500 });
                            // Click upload
                            const uploadButton = screen.getByText(/upload image/i);
                            fireEvent.click(uploadButton!);
                            // Wait for upload to complete or fail
                            if (shouldSucceed) {
                                await waitFor(() => {
                                    expect(mockOnUploaded).toHaveBeenCalled();
                                }, { timeout: 500 });
                                // On success, file is cleared, so button should be disabled (no file selected)
                                await waitFor(() => {
                                    const finalButton = screen.getByText(/upload image/i);
                                    expect(finalButton).toBeDisabled();
                                }, { timeout: 300 });
                            } else {
                                // Wait for error message to appear
                                await waitFor(() => {
                                    const errorMessage = screen.queryByText(/upload failed/i);
                                    expect(errorMessage).toBeTruthy();
                                }, { timeout: 500 });
                                // On failure, file remains selected, so button should be enabled
                                const finalButton = screen.getByText(/upload image/i);
                                expect(finalButton).not.toBeDisabled();
                            }
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
    });
});/**
 * Unit Tests for MediaUpload Component
 * Tests file validation, upload button disabled state, and error display
 * Requirements: 1.2, 1.4, 1.5
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor, cleanup } from '@testing-library/react';
import MediaUpload from './MediaUpload';
import * as mediaApi from '@/lib/mediaApi';
// Mock the mediaApi module
vi.mock('@/lib/mediaApi', () => ({
    uploadImage: vi.fn(),
}));
describe('MediaUpload - Unit Tests', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });
    afterEach(() => {
        cleanup();
    });
    describe('File Validation - Requirements 1.5', () => {
        it('should reject files with invalid type', async () => {
            const mockOnUploaded = vi.fn();
            const { container } = render(<MediaUpload onUploaded={mockOnUploaded} />);
            // Create an invalid file (PDF)
            const invalidFile = new File(['content'], 'document.pdf', { type: 'application/pdf' });
            // Get file input
            const fileInput = container.querySelector('input[type="file"]') as HTMLInputElement;
            expect(fileInput).toBeTruthy();
            // Simulate file selection
            Object.defineProperty(fileInput, 'files', {
                value: [invalidFile],
                writable: false,
            });
            fireEvent.change(fileInput);
            // Wait for error message
            await waitFor(() => {
                const errorMessage = screen.getByText(/invalid file type/i);
                expect(errorMessage).toBeTruthy();
            });
            // Verify no preview is shown
            const preview = container.querySelector('img[alt*="Preview"]');
            expect(preview).toBeFalsy();
        });
        it('should accept valid image types (JPEG, PNG, WebP, GIF)', async () => {
            const validTypes = [
                { type: 'image/jpeg', name: 'test.jpg' },
                { type: 'image/png', name: 'test.png' },
                { type: 'image/webp', name: 'test.webp' },
                { type: 'image/gif', name: 'test.gif' },
            ];
            for (const fileType of validTypes) {
                const mockOnUploaded = vi.fn();
                const { container, unmount } = render(<MediaUpload onUploaded={mockOnUploaded} />);
                // Create a valid file
                const validFile = new File(['content'], fileType.name, { type: fileType.type });
                // Get file input
                const fileInput = container.querySelector('input[type="file"]') as HTMLInputElement;
                // Simulate file selection
                Object.defineProperty(fileInput, 'files', {
                    value: [validFile],
                    writable: false,
