})'use client';
import { useState, useRef, ChangeEvent } from 'react';
import { uploadImages } from '@/lib/mediaApi';
/**
 * Props for MediaUpload component
 */
type MediaUploadProps = {
    onUploaded: (url: string) => void;
};
/**
 * Upload state type
 */
type UploadState = 'idle' | 'uploading' | 'error';
/**
 * MediaUpload Component
 * Handles multiple file selection, validation, and upload to MinIO storage
 */
export default function MediaUpload({ onUploaded }: MediaUploadProps) {
    const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
    const [uploadState, setUploadState] = useState<UploadState>('idle');
    const [error, setError] = useState<string | null>(null);
    const [previews, setPreviews] = useState<string[]>([]);
    const fileInputRef = useRef<HTMLInputElement>(null);
    /**
     * Handle file selection (multiple files)
     */
    const handleFileSelect = (event: ChangeEvent<HTMLInputElement>) => {
        const files = Array.from(event.target.files || []);
        if (files.length === 0) {
            return;
        }
        // Reset error state
        setError(null);
        // Validate file types and sizes
        const validTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
        const maxSize = 5 * 1024 * 1024; // 5MB in bytes
        const validFiles: File[] = [];
        const errors: string[] = [];
        for (const file of files) {
            if (!validTypes.includes(file.type)) {
                errors.push(`${file.name}: Invalid file type`);
                continue;
            }
            if (file.size > maxSize) {
                errors.push(`${file.name}: Exceeds 5MB limit`);
                continue;
            }
            validFiles.push(file);
        }
        if (errors.length > 0) {
            setError(errors.join(', '));
        }
        if (validFiles.length === 0) {
            setSelectedFiles([]);
            setPreviews([]);
            return;
        }
        // Set selected files
        setSelectedFiles(validFiles);
        // Generate previews for all valid files
        const previewPromises = validFiles.map((file) => {
            return new Promise<string>((resolve) => {
                const reader = new FileReader();
                reader.onloadend = () => {
                    resolve(reader.result as string);
                };
                reader.readAsDataURL(file);
            });
        });
        Promise.all(previewPromises).then((previewUrls) => {
            setPreviews(previewUrls);
        });
    };
    /**
     * Handle upload button click
     */
    const handleUpload = async () => {
        if (selectedFiles.length === 0) {
            return;
        }
        try {
            setUploadState('uploading');
            setError(null);
            // Call uploadImages API
            const response = await uploadImages(selectedFiles);
            // Reset state
            setUploadState('idle');
            setSelectedFiles([]);
            setPreviews([]);
            // Reset file input
            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
            // Call onUploaded callback for each URL
            response.urls.forEach((url) => {
                onUploaded(url);
            });
        } catch (err: any) {
            setUploadState('error');
            setError(err.message || 'Failed to upload images. Please try again.');
        }
    };
    /**
     * Handle clear selection
     */
    const handleClear = () => {
        setSelectedFiles([]);
        setPreviews([]);
        setError(null);
        setUploadState('idle');
        if (fileInputRef.current) {
            fileInputRef.current.value = '';
        }
    };
    /**
     * Handle remove single file
     */
    const handleRemoveFile = (index: number) => {
        setSelectedFiles((prev) => prev.filter((_, i) => i !== index));
        setPreviews((prev) => prev.filter((_, i) => i !== index));
    };
    const isUploading = uploadState === 'uploading';
    return (
        <div className="space-y-4">
            {/* File Input */}
            <div className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-6 text-center">
                <input
                    ref={fileInputRef}
                    type="file"
                    multiple
                    accept="image/jpeg,image/png,image/webp,image/gif"
                    onChange={handleFileSelect}
                    disabled={isUploading}
                    className="hidden"
                    id="file-upload"
                    aria-label="Select image files to upload"
                />
                <label
                    htmlFor="file-upload"
                    className={`cursor-pointer inline-flex flex-col items-center ${isUploading ? 'opacity-50 cursor-not-allowed' : ''
                        }`}
                >
                    <svg
                        className="w-12 h-12 text-gray-400 mb-3"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                    >
                        <path
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            strokeWidth={2}
                            d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                        />
                    </svg>
                    <span className="text-sm text-gray-600 dark:text-gray-400">
                        Click to select images (multiple)
                    </span>
                    <span className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                        JPEG, PNG, WebP, or GIF (max 5MB each, up to 10 files)
                    </span>
                </label>
            </div>
            {/* Previews Grid */}
            {previews.length > 0 && (
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                    {previews.map((preview, index) => (
                        <div key={index} className="relative group">
                            <img
                                src={preview}
                                alt={`Preview of ${selectedFiles[index]?.name || 'selected image'}`}
                                className="w-full h-32 object-cover rounded-lg border border-gray-300 dark:border-gray-600"
                            />
                            {!isUploading && (
                                <button
                                    onClick={() => handleRemoveFile(index)}
                                    className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 hover:bg-red-600 opacity-0 group-hover:opacity-100 transition-opacity"
                                    aria-label={`Remove ${selectedFiles[index]?.name}`}
                                >
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                                    </svg>
                                </button>
                            )}
                            <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 truncate">
                                {selectedFiles[index]?.name}
                            </p>
                        </div>
                    ))}
                </div>
            )}
            {/* File Count */}
            {selectedFiles.length > 0 && (
                <div className="text-sm text-gray-600 dark:text-gray-400 text-center">
                    {selectedFiles.length} file{selectedFiles.length !== 1 ? 's' : ''} selected
                </div>
            )}
            {/* Error Message */}
            {error && (
                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 text-red-700 dark:text-red-400 px-4 py-3 rounded-lg text-sm">
                    {error}
                </div>
            )}
            {/* Action Buttons */}
            <div className="flex gap-2">
                {selectedFiles.length > 0 && !isUploading && (
                    <button
                        onClick={handleClear}
                        className="flex-1 py-2 px-4 rounded-lg font-medium text-gray-700 dark:text-gray-300 bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors focus:outline-none focus:ring-2 focus:ring-gray-500"
                    >
                        Clear All
                    </button>
                )}
                <button
                    onClick={handleUpload}
                    disabled={selectedFiles.length === 0 || isUploading}
                    aria-label={isUploading ? 'Uploading images' : 'Upload selected images'}
                    className={`flex-1 py-2 px-4 rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 ${selectedFiles.length === 0 || isUploading
                        ? 'bg-gray-300 dark:bg-gray-700 text-gray-500 dark:text-gray-400 cursor-not-allowed'
                        : 'bg-blue-600 text-white hover:bg-blue-700'
                        }`}
                >
                    {isUploading ? (
                        <span className="flex items-center justify-center">
                            <svg
                                className="animate-spin -ml-1 mr-3 h-5 w-5 text-white"
                                xmlns="http://www.w3.org/2000/svg"
                                fill="none"
                                viewBox="0 0 24 24"
                            >
                                <circle
                                    className="opacity-25"
                                    cx="12"
                                    cy="12"
                                    r="10"
                                    stroke="currentColor"
                                    strokeWidth="4"
                                ></circle>
                                <path
                                    className="opacity-75"
                                    fill="currentColor"
                                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                                ></path>
                            </svg>
                            Uploading {selectedFiles.length} file{selectedFiles.length !== 1 ? 's' : ''}...
                        </span>
                    ) : (
                        `Upload ${selectedFiles.length > 0 ? `${selectedFiles.length} ` : ''}Image${selectedFiles.length !== 1 ? 's' : ''}`
                    )}
                </button>
            </div>
        </div>
    );
}"use client";
import { useState, useEffect } from "react";
import type { Category } from "../../lib/categoriesApi";
type CategoryFormProps = {
    category?: Category | null;
    onSave: (name: string) => Promise<void>;
    onCancel: () => void;
    isOpen: boolean;
};
export default function CategoryForm({
    category,
    onSave,
    onCancel,
    isOpen,
}: CategoryFormProps) {
    const [name, setName] = useState("");
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    useEffect(() => {
        if (category) {
            setName(category.name);
        } else {
            setName("");
        }
        setError(null);
    }, [category, isOpen]);
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        if (!name.trim()) {
            setError("El nombre es requerido");
            return;
        }
        try {
            setIsSubmitting(true);
            await onSave(name.trim());
            setName("");
        } catch (err: any) {
            setError(err.message || "Error al guardar categoría");
        } finally {
            setIsSubmitting(false);
        }
    };
    const handleCancel = () => {
        setName("");
        setError(null);
        onCancel();
    };
    if (!isOpen) return null;
    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md p-6 space-y-4">
                <h2 className="text-xl font-semibold text-slate-800">
                    {category ? "Editar Categoría" : "Nueva Categoría"}
                </h2>
                <form onSubmit={handleSubmit} className="space-y-4">
                    {/* Campo de nombre */}
                    <div>
                        <label
                            htmlFor="name"
                            className="block text-sm font-medium text-slate-700 mb-1"
                        >
                            Nombre de la categoría
                        </label>
                        <input
                            type="text"
                            id="name"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            disabled={isSubmitting}
                            placeholder="Ej: Limpieza del hogar"
                            className="
                w-full rounded-lg border border-slate-300 bg-white
                px-4 py-2 text-sm text-slate-800
                placeholder:text-slate-400
                focus:border-emerald-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/20
                disabled:opacity-50 disabled:cursor-not-allowed
              "
                        />
                    </div>
                    {/* Mensaje de error */}
                    {error && (
                        <div className="rounded-lg bg-rose-50 border border-rose-200 px-4 py-2 text-sm text-rose-700">
                            {error}
                        </div>
                    )}
                    {/* Botones */}
                    <div className="flex gap-3 justify-end pt-2">
                        <button
                            type="button"
                            onClick={handleCancel}
                            disabled={isSubmitting}
                            className="
                px-4 py-2 rounded-lg border border-slate-300
                text-sm font-medium text-slate-700
                hover:bg-slate-50
                disabled:opacity-50 disabled:cursor-not-allowed
                transition
              "
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="
                px-4 py-2 rounded-lg bg-emerald-600
                text-sm font-semibold text-white
                hover:bg-emerald-500
                disabled:opacity-50 disabled:cursor-not-allowed
                transition
              "
                        >
                            {isSubmitting ? "Guardando..." : "Guardar"}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}"use client";
import type { Category } from "../../lib/categoriesApi";
type CategoryTableProps = {
    categories: Category[];
    onEdit: (category: Category) => void;
    onDelete: (category: Category) => void;
    isLoading?: boolean;
};
export default function CategoryTable({
    categories,
    onEdit,
    onDelete,
    isLoading = false,
}: CategoryTableProps) {
    if (isLoading) {
        return (
            <div className="text-center py-12">
                <p className="text-slate-500">Cargando categorías...</p>
            </div>
        );
    }
    if (categories.length === 0) {
        return (
            <div className="text-center py-12 bg-slate-50 rounded-lg border border-slate-200">
                <p className="text-slate-500">No hay categorías creadas.</p>
                <p className="text-sm text-slate-400 mt-1">
                    Haz clic en "Nueva Categoría" para crear una.
                </p>
            </div>
        );
    }
    return (
        <div className="overflow-x-auto rounded-lg border border-slate-200">
            <table className="w-full">
                <thead className="bg-slate-50 border-b border-slate-200">
                    <tr>
                        <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                            ID
                        </th>
                        <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                            Nombre
                        </th>
                        <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                            Slug
                        </th>
                        <th className="px-4 py-3 text-left text-xs font-semibold text-slate-700 uppercase tracking-wider">
                            Productos
                        </th>
                        <th className="px-4 py-3 text-right text-xs font-semibold text-slate-700 uppercase tracking-wider">
                            Acciones
                        </th>
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-slate-200">
                    {categories.map((category) => (
                        <tr
                            key={category.id}
                            className="hover:bg-slate-50 transition"
                        >
                            <td className="px-4 py-3 text-sm text-slate-600">
                                {category.id}
                            </td>
                            <td className="px-4 py-3 text-sm font-medium text-slate-800">
                                {category.name}
                            </td>
                            <td className="px-4 py-3 text-sm text-slate-600 font-mono">
                                {category.slug}
                            </td>
                            <td className="px-4 py-3 text-sm text-slate-600">
                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-100 text-emerald-800">
                                    {category.productCount || 0} producto
                                    {category.productCount !== 1 ? "s" : ""}
                                </span>
                            </td>
                            <td className="px-4 py-3 text-sm text-right space-x-2">
                                <button
                                    onClick={() => onEdit(category)}
                                    className="
                    inline-flex items-center px-3 py-1.5 rounded-md
                    text-xs font-medium text-emerald-700 bg-emerald-50
                    hover:bg-emerald-100
                    transition
                  "
                                >
                                    Editar
                                </button>
                                <button
                                    onClick={() => onDelete(category)}
                                    className="
                    inline-flex items-center px-3 py-1.5 rounded-md
                    text-xs font-medium text-rose-700 bg-rose-50
                    hover:bg-rose-100
                    transition
                  "
                                >
                                    Eliminar
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
}/**
 * Property-Based Tests for ProductForm Integration with MediaPicker
 * 
 * Property 16: Product form integration data flow
 * **Feature: media-picker, Property 16: Product form integration data flow**
 * **Validates: Requirements 5.2**
 * 
 * Property 17: Product form displays selected images
 * **Feature: media-picker, Property 17: Product form displays selected images**
 * **Validates: Requirements 5.3**
 * 
 * Property 18: Product form submission includes images
 * **Feature: media-picker, Property 18: Product form submission includes images**
 * **Validates: Requirements 5.4**
 * 
 * Property 19: Edit mode pre-population
 * **Feature: media-picker, Property 19: Edit mode pre-population**
 * **Validates: Requirements 5.5**
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor, cleanup } from '@testing-library/react';
import * as fc from 'fast-check';
import ProductForm from './ProductForm';
import * as mediaApi from '@/lib/mediaApi';
import type { Product } from '@/lib/types';
import type { Category } from '@/lib/categoriesApi';
// Mock the mediaApi module
vi.mock('@/lib/mediaApi', () => ({
    uploadImage: vi.fn(),
    listImages: vi.fn(),
}));
describe('ProductForm - Property-Based Tests', () => {
    const mockCategories: Category[] = [
        { id: 1, name: 'Category 1', slug: 'category-1' },
        { id: 2, name: 'Category 2', slug: 'category-2' },
    ];
    beforeEach(() => {
        vi.clearAllMocks();
    });
    afterEach(() => {
        cleanup();
    });
    describe('Property 16: Product form integration data flow', () => {
        /**
         * **Feature: media-picker, Property 16: Product form integration data flow**
         * For any images selected in the media picker, the product form should receive 
         * the exact array of selected URLs when the picker closes.
         */
        it('should receive exact array of selected URLs from MediaPicker', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate array of image URLs (1-5 images)
                    fc.array(
                        fc.webUrl({ withFragments: false, withQueryParameters: false }),
                        { minLength: 1, maxLength: 5 }
                    ),
                    async (imageUrls) => {
                        const uniqueUrls = Array.from(new Set(imageUrls));
                        if (uniqueUrls.length === 0) return true;
                        // Mock listImages to return our test images
                        vi.mocked(mediaApi.listImages).mockResolvedValue(uniqueUrls);
                        const mockOnSave = vi.fn();
                        const mockOnClose = vi.fn();
                        const { container, unmount } = render(
                            <ProductForm
                                open={true}
                                onClose={mockOnClose}
                                onSave={mockOnSave}
                                categories={mockCategories}
                            />
                        );
                        try {
                            // Wait for form to render
                            await waitFor(() => {
                                const form = container.querySelector('form');
                                expect(form).toBeTruthy();
                            }, { timeout: 1000 });
                            // Click "Select Images" button
                            const selectImagesButton = screen.getByRole('button', { name: /seleccionar imágenes/i });
                            fireEvent.click(selectImagesButton);
                            // Wait for MediaPicker to open
                            await waitFor(() => {
                                const dialog = screen.getByRole('dialog');
                                expect(dialog).toBeTruthy();
                            }, { timeout: 1000 });
                            // Wait for images to load in MediaPicker
                            await waitFor(() => {
                                const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                                expect(imageContainers.length).toBeGreaterThan(0);
                            }, { timeout: 1000 });
                            // Select all images
                            const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                            for (let i = 0; i < imageContainers.length; i++) {
                                fireEvent.click(imageContainers[i]);
                            }
                            // Wait for selections
                            await waitFor(() => {
                                const selected = container.querySelectorAll('.bg-blue-500\\/20');
                                expect(selected.length).toBe(imageContainers.length);
                            }, { timeout: 500 });
                            // Click Select button in MediaPicker
                            const selectButton = screen.getByRole('button', { name: /select \(\d+\)/i });
                            fireEvent.click(selectButton);
                            // Wait for MediaPicker to close and images to appear in form
                            await waitFor(() => {
                                const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                                expect(thumbnails.length).toBe(uniqueUrls.length);
                            }, { timeout: 1000 });
                            // Verify the form has the correct image URLs
                            const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                            const displayedUrls = Array.from(thumbnails).map(img => (img as HTMLImageElement).src);
                            // Normalize URLs for comparison (browser may add/remove trailing slashes and dots)
                            const normalizeUrl = (url: string) => {
                                try {
                                    const urlObj = new URL(url);
                                    return urlObj.href.replace(/\/+$/, '').replace(/\.+$/, '');
                                } catch {
                                    return url.replace(/\/+$/, '').replace(/\.+$/, '');
                                }
                            };
                            const normalizedDisplayed = displayedUrls.map(normalizeUrl);
                            const normalizedExpected = uniqueUrls.map(normalizeUrl);
                            // All selected URLs should be displayed
                            expect(displayedUrls.length).toBe(uniqueUrls.length);
                            normalizedExpected.forEach(url => {
                                expect(normalizedDisplayed.some(displayedUrl => displayedUrl === url)).toBe(true);
                            });
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
    });
    describe('Property 17: Product form displays selected images', () => {
        /**
         * **Feature: media-picker, Property 17: Product form displays selected images**
         * For any images selected via the media picker, the product form should display 
         * thumbnails of those images after the picker closes.
         */
        it('should display thumbnails for all selected images', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate array of image URLs (1-6 images)
                    fc.array(
                        fc.webUrl({ withFragments: false, withQueryParameters: false }),
                        { minLength: 1, maxLength: 6 }
                    ),
                    async (imageUrls) => {
                        const uniqueUrls = Array.from(new Set(imageUrls));
                        if (uniqueUrls.length === 0) return true;
                        vi.mocked(mediaApi.listImages).mockResolvedValue(uniqueUrls);
                        const mockOnSave = vi.fn();
                        const mockOnClose = vi.fn();
                        const { container, unmount } = render(
                            <ProductForm
                                open={true}
                                onClose={mockOnClose}
                                onSave={mockOnSave}
                                categories={mockCategories}
                            />
                        );
                        try {
                            // Open MediaPicker
                            const selectImagesButton = screen.getByRole('button', { name: /seleccionar imágenes/i });
                            fireEvent.click(selectImagesButton);
                            // Wait for MediaPicker
                            await waitFor(() => {
                                const dialog = screen.getByRole('dialog');
                                expect(dialog).toBeTruthy();
                            }, { timeout: 1000 });
                            // Wait for images to load
                            await waitFor(() => {
                                const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                                expect(imageContainers.length).toBeGreaterThan(0);
                            }, { timeout: 1000 });
                            // Select all images
                            const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                            for (let i = 0; i < imageContainers.length; i++) {
                                fireEvent.click(imageContainers[i]);
                            }
                            // Click Select
                            await waitFor(() => {
                                const selectButton = screen.getByRole('button', { name: /select \(\d+\)/i });
                                fireEvent.click(selectButton);
                            }, { timeout: 500 });
                            // Verify thumbnails are displayed
                            await waitFor(() => {
                                const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                                expect(thumbnails.length).toBe(uniqueUrls.length);
                                // Each thumbnail should have a remove button
                                const removeButtons = container.querySelectorAll('button[aria-label="Eliminar imagen"]');
                                expect(removeButtons.length).toBe(uniqueUrls.length);
                            }, { timeout: 1000 });
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
        it('should allow removing individual images from thumbnails', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate array of at least 2 images
                    fc.array(
                        fc.webUrl({ withFragments: false, withQueryParameters: false }),
                        { minLength: 2, maxLength: 5 }
                    ),
                    async (imageUrls) => {
                        const uniqueUrls = Array.from(new Set(imageUrls));
                        if (uniqueUrls.length < 2) return true;
                        vi.mocked(mediaApi.listImages).mockResolvedValue(uniqueUrls);
                        const mockOnSave = vi.fn();
                        const mockOnClose = vi.fn();
                        const { container, unmount } = render(
                            <ProductForm
                                open={true}
                                onClose={mockOnClose}
                                onSave={mockOnSave}
                                categories={mockCategories}
                            />
                        );
                        try {
                            // Select images via MediaPicker
                            const selectImagesButton = screen.getByRole('button', { name: /seleccionar imágenes/i });
                            fireEvent.click(selectImagesButton);
                            await waitFor(() => {
                                const dialog = screen.getByRole('dialog');
                                expect(dialog).toBeTruthy();
                            }, { timeout: 1000 });
                            await waitFor(() => {
                                const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                                expect(imageContainers.length).toBeGreaterThan(0);
                            }, { timeout: 1000 });
                            const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                            for (let i = 0; i < imageContainers.length; i++) {
                                fireEvent.click(imageContainers[i]);
                            }
                            await waitFor(() => {
                                const selectButton = screen.getByRole('button', { name: /select \(\d+\)/i });
                                fireEvent.click(selectButton);
                            }, { timeout: 500 });
                            // Wait for thumbnails
                            await waitFor(() => {
                                const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                                expect(thumbnails.length).toBe(uniqueUrls.length);
                            }, { timeout: 1000 });
                            // Remove first image
                            const removeButtons = container.querySelectorAll('button[aria-label="Eliminar imagen"]');
                            const firstRemoveButton = removeButtons[0] as HTMLElement;
                            // Hover to make button visible
                            fireEvent.mouseEnter(firstRemoveButton.closest('.group')!);
                            fireEvent.click(firstRemoveButton);
                            // Verify one less thumbnail
                            await waitFor(() => {
                                const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                                expect(thumbnails.length).toBe(uniqueUrls.length - 1);
                            }, { timeout: 500 });
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
    });
    describe('Property 18: Product form submission includes images', () => {
        /**
         * **Feature: media-picker, Property 18: Product form submission includes images**
         * For any product form submission, the submitted data should include all image URLs 
         * that were selected via the media picker.
         */
        it('should include all selected images in form submission', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate product data
                    fc.record({
                        name: fc.string({ minLength: 1, maxLength: 50 }),
                        price: fc.integer({ min: 1, max: 100000 }),
                        stock: fc.integer({ min: 0, max: 1000 }),
                        imageUrls: fc.array(
                            fc.webUrl({ withFragments: false, withQueryParameters: false }),
                            { minLength: 1, maxLength: 4 }
                        ),
                    }),
                    async ({ name, price, stock, imageUrls }) => {
                        const uniqueUrls = Array.from(new Set(imageUrls));
                        if (uniqueUrls.length === 0) return true;
                        vi.mocked(mediaApi.listImages).mockResolvedValue(uniqueUrls);
                        const mockOnSave = vi.fn().mockResolvedValue(undefined);
                        const mockOnClose = vi.fn();
                        const { container, unmount } = render(
                            <ProductForm
                                open={true}
                                onClose={mockOnClose}
                                onSave={mockOnSave}
                                categories={mockCategories}
                            />
                        );
                        try {
                            // Fill form fields
                            const nameInput = screen.getByPlaceholderText(/ej: cloro líquido/i);
                            fireEvent.change(nameInput, { target: { value: name } });
                            const priceInput = container.querySelector('input[type="number"][min="0"][step="1"]') as HTMLInputElement;
                            fireEvent.change(priceInput, { target: { value: price.toString() } });
                            const stockInputs = container.querySelectorAll('input[type="number"]');
                            const stockInput = Array.from(stockInputs).find(input =>
                                (input as HTMLInputElement).value === '0' &&
                                input.previousElementSibling?.textContent?.includes('Stock')
                            ) as HTMLInputElement;
                            if (stockInput) {
                                fireEvent.change(stockInput, { target: { value: stock.toString() } });
                            }
                            const categorySelect = container.querySelector('select') as HTMLSelectElement;
                            fireEvent.change(categorySelect, { target: { value: '1' } });
                            // Select images
                            const selectImagesButton = screen.getByRole('button', { name: /seleccionar imágenes/i });
                            fireEvent.click(selectImagesButton);
                            await waitFor(() => {
                                const dialog = screen.getByRole('dialog');
                                expect(dialog).toBeTruthy();
                            }, { timeout: 1000 });
                            await waitFor(() => {
                                const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                                expect(imageContainers.length).toBeGreaterThan(0);
                            }, { timeout: 1000 });
                            const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                            for (let i = 0; i < imageContainers.length; i++) {
                                fireEvent.click(imageContainers[i]);
                            }
                            await waitFor(() => {
                                const selectButton = screen.getByRole('button', { name: /select \(\d+\)/i });
                                fireEvent.click(selectButton);
                            }, { timeout: 500 });
                            // Wait for thumbnails
                            await waitFor(() => {
                                const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                                expect(thumbnails.length).toBe(uniqueUrls.length);
                            }, { timeout: 1000 });
                            // Submit form
                            const submitButton = screen.getByRole('button', { name: /guardar/i });
                            fireEvent.click(submitButton);
                            // Verify onSave was called with images array
                            await waitFor(() => {
                                expect(mockOnSave).toHaveBeenCalledTimes(1);
                                const submittedData = mockOnSave.mock.calls[0][0];
                                expect(Array.isArray(submittedData.imageUrl)).toBe(true);
                                expect(submittedData.imageUrl.length).toBe(uniqueUrls.length);
                                // Verify all URLs are included
                                uniqueUrls.forEach(url => {
                                    expect(submittedData.imageUrl).toContain(url);
                                });
                            }, { timeout: 1000 });
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
        it('should validate that at least one image is required', async () => {
            await fc.assert(
                fc.asyncProperty(
                    fc.string({ minLength: 1, maxLength: 50 }),
                    async (productName) => {
                        vi.mocked(mediaApi.listImages).mockResolvedValue([]);
                        const mockOnSave = vi.fn();
                        const mockOnClose = vi.fn();
                        const { container, unmount } = render(
                            <ProductForm
                                open={true}
                                onClose={mockOnClose}
                                onSave={mockOnSave}
                                categories={mockCategories}
                            />
                        );
                        try {
                            // Fill only required fields except images
                            const nameInput = screen.getByPlaceholderText(/ej: cloro líquido/i);
                            fireEvent.change(nameInput, { target: { value: productName } });
                            const priceInput = container.querySelector('input[type="number"][min="0"][step="1"]') as HTMLInputElement;
                            fireEvent.change(priceInput, { target: { value: '1000' } });
                            const categorySelect = container.querySelector('select') as HTMLSelectElement;
                            fireEvent.change(categorySelect, { target: { value: '1' } });
                            // Try to submit without images
                            const submitButton = screen.getByRole('button', { name: /guardar/i });
                            fireEvent.click(submitButton);
                            // Verify validation error is shown
                            await waitFor(() => {
                                const errorMessage = screen.getByText(/se requiere al menos una imagen/i);
                                expect(errorMessage).toBeTruthy();
                            }, { timeout: 500 });
                            // Verify onSave was NOT called
                            expect(mockOnSave).not.toHaveBeenCalled();
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
    });
    describe('Property 19: Edit mode pre-population', () => {
        /**
         * **Feature: media-picker, Property 19: Edit mode pre-population**
         * For any existing product being edited, opening the media picker should pre-select 
         * the images that are currently associated with that product.
         */
        it('should pre-populate form with existing product images', async () => {
            await fc.assert(
                fc.asyncProperty(
                    // Generate product with images
                    fc.record({
                        id: fc.integer({ min: 1, max: 1000 }),
                        name: fc.string({ minLength: 1, maxLength: 50 }),
                        price: fc.integer({ min: 1, max: 100000 }),
                        stock: fc.integer({ min: 0, max: 1000 }),
                        imageUrls: fc.array(
                            fc.webUrl({ withFragments: false, withQueryParameters: false }),
                            { minLength: 1, maxLength: 4 }
                        ),
                    }),
                    async ({ id, name, price, stock, imageUrls }) => {
                        const uniqueUrls = Array.from(new Set(imageUrls));
                        if (uniqueUrls.length === 0) return true;
                        // Create mock product with images
                        const mockProduct: Product = {
                            id,
                            name,
                            slug: name.toLowerCase().replace(/\s+/g, '-'),
                            description: 'Test product',
                            price,
                            stock,
                            imageUrl: uniqueUrls[0], // Use first image as string
                            category: mockCategories[0],
                            isFeatured: false,
                            isOnSale: false,
                            discountPercent: null,
                        };
                        vi.mocked(mediaApi.listImages).mockResolvedValue(uniqueUrls);
                        const mockOnSave = vi.fn();
                        const mockOnClose = vi.fn();
                        const { container, unmount } = render(
                            <ProductForm
                                open={true}
                                onClose={mockOnClose}
                                onSave={mockOnSave}
                                product={mockProduct}
                                categories={mockCategories}
                            />
                        );
                        try {
                            // Wait for form to render with product data
                            await waitFor(() => {
                                const form = container.querySelector('form');
                                expect(form).toBeTruthy();
                            }, { timeout: 1000 });
                            // Verify images are displayed as thumbnails
                            await waitFor(() => {
                                const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                                expect(thumbnails.length).toBe(uniqueUrls.length);
                            }, { timeout: 500 });
                            // Open MediaPicker to verify pre-selection
                            const selectImagesButton = screen.getByRole('button', { name: /seleccionar imágenes/i });
                            fireEvent.click(selectImagesButton);
                            await waitFor(() => {
                                const dialog = screen.getByRole('dialog');
                                expect(dialog).toBeTruthy();
                            }, { timeout: 1000 });
                            // Wait for images to load
                            await waitFor(() => {
                                const imageContainers = container.querySelectorAll('[class*="aspect-square"]');
                                expect(imageContainers.length).toBeGreaterThan(0);
                            }, { timeout: 1000 });
                            // Verify that the product's images are pre-selected in MediaPicker
                            await waitFor(() => {
                                const selectedIndicators = container.querySelectorAll('.bg-blue-500\\/20');
                                expect(selectedIndicators.length).toBe(uniqueUrls.length);
                            }, { timeout: 500 });
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
        it('should handle products with single imageUrl string in edit mode', async () => {
            await fc.assert(
                fc.asyncProperty(
                    fc.record({
                        id: fc.integer({ min: 1, max: 1000 }),
                        name: fc.string({ minLength: 1, maxLength: 50 }),
                        imageUrl: fc.webUrl({ withFragments: false, withQueryParameters: false }),
                    }),
                    async ({ id, name, imageUrl }) => {
                        // Create mock product with single imageUrl string (backward compatibility)
                        const mockProduct: Product = {
                            id,
                            name,
                            slug: name.toLowerCase().replace(/\s+/g, '-'),
                            description: 'Test product',
                            price: 1000,
                            stock: 10,
                            imageUrl: imageUrl, // Single string, not array
                            category: mockCategories[0],
                            isFeatured: false,
                            isOnSale: false,
                            discountPercent: null,
                        };
                        vi.mocked(mediaApi.listImages).mockResolvedValue([imageUrl]);
                        const mockOnSave = vi.fn();
                        const mockOnClose = vi.fn();
                        const { container, unmount } = render(
                            <ProductForm
                                open={true}
                                onClose={mockOnClose}
                                onSave={mockOnSave}
                                product={mockProduct}
                                categories={mockCategories}
                            />
                        );
                        try {
                            // Wait for form to render
                            await waitFor(() => {
                                const form = container.querySelector('form');
                                expect(form).toBeTruthy();
                            }, { timeout: 1000 });
                            // Verify single image is displayed as thumbnail
                            await waitFor(() => {
                                const thumbnails = container.querySelectorAll('img[alt*="Producto imagen"]');
                                expect(thumbnails.length).toBe(1);
                                // Normalize URLs for comparison (browser may add/remove trailing slashes and dots)
                                const normalizeUrl = (url: string) => {
                                    try {
                                        const urlObj = new URL(url);
                                        return urlObj.href.replace(/\/+$/, '').replace(/\.+$/, '');
                                    } catch {
                                        return url.replace(/\/+$/, '').replace(/\.+$/, '');
                                    }
                                };
                                expect(normalizeUrl((thumbnails[0] as HTMLImageElement).src)).toBe(normalizeUrl(imageUrl));
                            }, { timeout: 500 });
                        } finally {
                            unmount();
                        }
                        return true;
                    }
                ),
                { numRuns: 100 }
            );
        }, 30000);
    });
});"use client";
import { useState, useEffect } from "react";
import type { Product } from "../../lib/types";
import type { Category } from "../../lib/categoriesApi";
import type { CreateProductDto } from "../../lib/productsApi";
import MediaPicker from "./media/MediaPicker";
import { toNumber, formatPriceInput, parsePriceInput } from "../../lib/price";
// Internal form data type that supports multiple images
type ProductFormData = Omit<CreateProductDto, 'imageUrl'> & {
    imageUrl: string[]; // Internal state uses array
};
type ProductFormProps = {
    open: boolean;
    onClose: () => void;
    onSave: (data: CreateProductDto) => Promise<void>;
    product?: Product | null;
    categories: Category[];
};
export default function ProductForm({
    open,
    onClose,
    onSave,
    product,
    categories,
}: ProductFormProps) {
    const [formData, setFormData] = useState<ProductFormData>({
        name: "",
        description: "",
        price: 0,
        slug: "",
        stock: 0,
        imageUrl: [],
        categoryId: 0,
        isFeatured: false,
        isOnSale: false,
        discountPercent: null,
    });
    const [errors, setErrors] = useState<Record<string, string>>({});
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isMediaPickerOpen, setIsMediaPickerOpen] = useState(false);
    const [priceDisplay, setPriceDisplay] = useState("");
    // Cargar datos del producto al abrir para edición
    useEffect(() => {
        if (open) {
            if (product) {
                // Modo edición
                // Convert imageUrl to array if it's a string
                const images = Array.isArray(product.imageUrl)
                    ? product.imageUrl
                    : product.imageUrl
                        ? [product.imageUrl]
                        : [];
                const price = toNumber(product.price);
                setFormData({
                    name: product.name,
                    description: product.description || "",
                    price: price,
                    slug: product.slug || "",
                    stock: product.stock || 0,
                    imageUrl: images,
                    categoryId: product.category?.id || 0,
                    isFeatured: product.isFeatured || false,
                    isOnSale: product.isOnSale || false,
                    discountPercent: product.discountPercent || null,
                });
                setPriceDisplay(formatPriceInput(price.toString()));
            } else {
                // Modo creación
                setFormData({
                    name: "",
                    description: "",
                    price: 0,
                    slug: "",
                    stock: 0,
                    imageUrl: [],
                    categoryId: 0,
                    isFeatured: false,
                    isOnSale: false,
                    discountPercent: null,
                });
                setPriceDisplay("");
            }
            setErrors({});
        }
    }, [open, product]);
    // Validar formulario
    const validate = (): boolean => {
        const newErrors: Record<string, string> = {};
        if (!formData.name.trim()) {
            newErrors.name = "El nombre es requerido";
        }
        if (formData.price <= 0) {
            newErrors.price = "El precio debe ser mayor a 0";
        }
        if (formData.stock < 0) {
            newErrors.stock = "El stock no puede ser negativo";
        }
        // Validate images array
        const images = Array.isArray(formData.imageUrl) ? formData.imageUrl : [];
        if (images.length === 0) {
            newErrors.imageUrl = "Se requiere al menos una imagen";
        }
        if (!formData.categoryId || formData.categoryId === 0) {
            newErrors.categoryId = "La categoría es requerida";
        }
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };
    // Generate slug from name
    const generateSlug = (name: string): string => {
        return name
            .toLowerCase()
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '') // Remove accents
            .replace(/[^a-z0-9\s-]/g, '') // Remove special chars
            .trim()
            .replace(/\s+/g, '-') // Replace spaces with hyphens
            .replace(/-+/g, '-'); // Remove duplicate hyphens
    };
    // Manejar submit
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validate()) {
            return;
        }
        try {
            setIsSubmitting(true);
            // Convert images array to single string for backend compatibility
            const images = Array.isArray(formData.imageUrl)
                ? formData.imageUrl.filter((url: string) => url && url.trim() !== '')
                : [];
            // Build data object without imageUrl first
            const { imageUrl: _, ...restData } = formData;
            const dataToSend: any = { ...restData };
            // Auto-generate slug if not provided or empty
            if (!dataToSend.slug || dataToSend.slug.trim() === '') {
                dataToSend.slug = generateSlug(formData.name);
            }
            // Only include imageUrl if we have at least one valid image URL
            if (images.length > 0) {
                dataToSend.imageUrl = images[0];
            }
            // If no images, imageUrl field is completely omitted
            console.log('Sending data to backend:', JSON.stringify(dataToSend, null, 2)); // Debug log
            await onSave(dataToSend);
            // El componente padre cerrará el modal y mostrará notificación
        } catch (error: any) {
            // El error se maneja en el componente padre
            console.error("Error en formulario:", error);
        } finally {
            setIsSubmitting(false);
        }
    };
    // Manejar cierre
    const handleClose = () => {
        if (!isSubmitting) {
            setFormData({
                name: "",
                description: "",
                price: 0,
                slug: "",
                stock: 0,
                imageUrl: [],
                categoryId: 0,
                isFeatured: false,
                isOnSale: false,
                discountPercent: null,
            });
            setErrors({});
            setIsMediaPickerOpen(false);
            setPriceDisplay("");
            onClose();
        }
    };
    // Manejar selección de imágenes desde MediaPicker
    const handleImagesSelected = (urls: string[]) => {
        // Combine new URLs with existing ones, avoiding duplicates
        const existingUrls = Array.isArray(formData.imageUrl) ? formData.imageUrl : [];
        const newUrls = urls.filter(url => !existingUrls.includes(url));
        const combinedUrls = [...existingUrls, ...newUrls];
        setFormData({ ...formData, imageUrl: combinedUrls });
        // Don't close the picker automatically - let user continue browsing/uploading
    };
    // Manejar cambio de precio con formato automático
    const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        const formatted = formatPriceInput(value);
        const numericValue = parsePriceInput(formatted);
