                                    disabled={isSubmitting}
                                    className="
                    w-20 rounded-lg border border-slate-300 bg-white
                    px-2 py-1 text-sm text-slate-800
                    focus:border-emerald-500 focus:outline-none
                    disabled:opacity-50 disabled:cursor-not-allowed
                  "
                                />
