                multiple={true}
                initialSelection={Array.isArray(formData.imageUrl) ? formData.imageUrl : []}
                onSelect={handleImagesSelected}
                onClose={() => setIsMediaPickerOpen(false)}
            />
        </div>
    );
}"use client";
import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
export type LocalUser = {
  id: string;
  name: string;
  email: string;
  password: string;
  role: "admin" | "user";
};
type AuthContextType = {
  user: LocalUser | null;
  loading: boolean;
  isAuthenticated: boolean;
  isAdmin: boolean;
  login: (email: string, password: string) => Promise<boolean>;
  register: (name: string, email: string, password: string) => Promise<boolean>;
  logout: () => void;
};
const AuthContext = createContext<AuthContextType | null>(null);
export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<LocalUser | null>(null);
  const [loading, setLoading] = useState(true);
  // Cargar usuario guardado en localStorage al iniciar
  useEffect(() => {
    if (typeof window === "undefined") return;
    const saved = localStorage.getItem("authUser");
    if (saved) {
      try {
        setUser(JSON.parse(saved));
      } catch {
        localStorage.removeItem("authUser");
      }
    }
    setLoading(false);
  }, []);
  const login = async (email: string, password: string) => {
    if (typeof window === "undefined") return false;
    const raw = localStorage.getItem("users");
    const users: LocalUser[] = raw ? JSON.parse(raw) : [];
    const found = users.find(
      (u) => u.email === email && u.password === password
    );
    if (!found) return false;
    localStorage.setItem("authUser", JSON.stringify(found));
    setUser(found);
    return true;
  };
  const register = async (name: string, email: string, password: string) => {
    if (typeof window === "undefined") return false;
    const stored = localStorage.getItem("users");
    const users: LocalUser[] = stored ? JSON.parse(stored) : [];
    // correo ya registrado
    if (users.some((u) => u.email === email)) {
      return false;
    }
    // primer usuario o correo especial → admin
    const role: "admin" | "user" =
      users.length === 0 || email === "cleaningsale04@gmail.com"
        ? "admin"
        : "user";
    const newUser: LocalUser = {
      id: crypto.randomUUID(),
      name,
      email,
      password,
      role,
    };
    users.push(newUser);
    localStorage.setItem("users", JSON.stringify(users));
    // lo dejamos registrado pero no logueado automáticamente
    return true;
  };
  const logout = () => {
    if (typeof window !== "undefined") {
      localStorage.removeItem("authUser");
    }
    setUser(null);
  };
  const value: AuthContextType = {
    user,
    loading,
    isAuthenticated: !!user,
    isAdmin: !!user && user.role === "admin",
    login,
    register,
    logout,
  };
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}
export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth debe usarse dentro de <AuthProvider>");
  }
  return ctx;
}"use client";
import { ReactNode, useEffect } from "react";
import { useRouter, usePathname } from "next/navigation";
import { useAuth } from "../../contexts/AuthContext";
type Props = {
  children: ReactNode;
};
export default function RequireAdmin({ children }: Props) {
  const { isAdmin, isAuthenticated, loading } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  useEffect(() => {
    if (loading) return;
    // si no está autenticado, lo mando a login
    if (!isAuthenticated) {
      router.replace(`/auth/login?redirect=${encodeURIComponent(pathname)}`);
      return;
    }
    // si está logueado pero no es admin, lo mando a home
    if (!isAdmin) {
      router.replace("/");
    }
  }, [loading, isAuthenticated, isAdmin, router, pathname]);
  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-emerald-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-sm text-muted-foreground">
            Verificando permisos...
          </p>
        </div>
      </div>
    );
  }
  if (!isAuthenticated || !isAdmin) {
    return null; // ya está redirigiendo
  }
  return <>{children}</>;
}"use client";
import { useAuth } from "../../contexts/AuthContext";
import { useRouter, usePathname } from "next/navigation";
import { useEffect } from "react";
export function RequireAuth({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  useEffect(() => {
    if (!loading && !user) {
      // Redirigir a login con la ruta actual como parámetro
      router.push(`/auth/login?redirect=${encodeURIComponent(pathname)}`);
    }
  }, [loading, user, router, pathname]);
  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="text-center">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-emerald-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-sm text-muted-foreground">Verificando sesión...</p>
        </div>
      </div>
    );
  }
  if (!user) return null;
  return <>{children}</>;
