import { useEffect, useMemo, useState } from "react";
import type { Product } from "../../lib/types";
import ProductCard from "../products/productCard";
type OffersCarouselProps = {
  products: Product[];
  title?: string;
  subtitle?: string;
  autoPlayIntervalMs?: number;
};
export default function OffersCarousel({
  products,
  title = "Ofertas y productos destacados",
  subtitle = "Selección especial para ti",
  autoPlayIntervalMs = 6000,
}: OffersCarouselProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [itemsPerPage, setItemsPerPage] = useState(4);
  const total = products.length;
  if (!total) return null;
  // ───── RESPONSIVE: decidir cuántos ítems mostrar ─────
 // ───── RESPONSIVE: decidir cuántos ítems mostrar ─────
    useEffect(() => {
    const updateItems = () => {
      const w = window.innerWidth;
      if (w < 480) {
        // teléfonos pequeños
        setItemsPerPage(1);
      } else if (w < 768) {
        // teléfonos grandes / phablets
        setItemsPerPage(2);
      } else if (w < 1024) {
        // tablets
        setItemsPerPage(3);
      } else if (w < 1440) {
        // notebooks / monitores estándar
        setItemsPerPage(4);
      } else {
        // pantallas grandes
        setItemsPerPage(6);
      }
    };
    updateItems();
    window.addEventListener("resize", updateItems);
    return () => window.removeEventListener("resize", updateItems);
  }, []);
  const safeItemsPerPage = Math.min(itemsPerPage, total);
  // ───── Navegación ─────
  const goNext = () => setCurrentIndex((prev) => (prev + 1) % total);
  const goPrev = () => setCurrentIndex((prev) => (prev - 1 + total) % total);
  useEffect(() => {
    const id = setInterval(goNext, autoPlayIntervalMs);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [total, autoPlayIntervalMs]);
  // ───── Ventana visible ─────
  const visibleProducts = useMemo(() => {
    const result: Product[] = [];
    for (let i = 0; i < safeItemsPerPage; i++) {
      const idx = (currentIndex + i) % total;
      result.push(products[idx]);
    }
    return result;
  }, [products, currentIndex, safeItemsPerPage, total]);
  return (
    <section className="space-y-3">
      {/* Encabezado */}
      <div className="flex items-center justify-between max-w-6xl mx-auto px-1">
        <div>
          <h2 className="text-lg font-semibold text-emerald-800">{title}</h2>
          {subtitle && (
            <p className="text-xs text-slate-500">{subtitle}</p>
          )}
        </div>
        {/* Controles desktop/tablet */}
        <div className="hidden sm:flex items-center gap-2">
          <button
            type="button"
            onClick={goPrev}
            className="flex h-7 w-7 items-center justify-center rounded-full border border-emerald-200 text-emerald-700 hover:bg-emerald-50 transition"
            aria-label="Anterior"
          >
            ‹
          </button>
          <button
            type="button"
            onClick={goNext}
            className="flex h-7 w-7 items-center justify-center rounded-full border border-emerald-200 text-emerald-700 hover:bg-emerald-50 transition"
            aria-label="Siguiente"
          >
            ›
          </button>
        </div>
      </div>
      {/* Carrusel */}
      <div className="relative max-w-6xl mx-auto">
        <div className="overflow-hidden">
          <div className="flex gap-4">
            {visibleProducts.map((p) => (
              <div
                key={p.id}
                style={{ flex: `0 0 ${100 / safeItemsPerPage}%` }}
                className="min-w-0"
              >
                {/* IMPORTANTE: ProductCard debe respetar w-full */}
                <ProductCard p={p} />
              </div>
            ))}
          </div>
        </div>
        {/* Controles móviles flotantes */}
        <div className="sm:hidden absolute -right-1 -top-9 flex items-center gap-2">
          <button
            type="button"
            onClick={goPrev}
            className="flex h-7 w-7 items-center justify-center rounded-full border border-emerald-200 bg-white/80 text-emerald-700 hover:bg-emerald-50 transition"
            aria-label="Anterior"
          >
            ‹
          </button>
          <button
            type="button"
            onClick={goNext}
            className="flex h-7 w-7 items-center justify-center rounded-full border border-emerald-200 bg-white/80 text-emerald-700 hover:bg-emerald-50 transition"
            aria-label="Siguiente"
          >
            ›
          </button>
        </div>
      </div>
    </section>
  );
}// web/components/carousel/priceRangeFilter.tsx
"use client";
import { useEffect, useState } from "react";
type PriceRangeFilterProps = {
  maxLimit: number;
  initialMaxPrice?: number;
};
const currencyCLP = new Intl.NumberFormat("es-CL", {
  style: "currency",
  currency: "CLP",
  maximumFractionDigits: 0,
});
export default function PriceRangeFilter({
  maxLimit,
  initialMaxPrice,
}: PriceRangeFilterProps) {
  const [value, setValue] = useState(
    initialMaxPrice && !Number.isNaN(initialMaxPrice)
      ? initialMaxPrice
      : maxLimit
  );
  // Si cambian los props (por navegación con filtros) actualizamos el slider
  useEffect(() => {
    setValue(
      initialMaxPrice && !Number.isNaN(initialMaxPrice)
        ? initialMaxPrice
        : maxLimit
    );
  }, [initialMaxPrice, maxLimit]);
  return (
    <div className="space-y-3 rounded-2xl border border-emerald-200 bg-white/70 px-3 py-3 text-sm">
      <p className="text-sm font-semibold text-emerald-800 uppercase tracking-wide">
        Filtrar por precio
      </p>
      {/* Valor actual */}
      <div className="flex items-baseline justify-between">
        <span className="text-emerald-700 font-medium">
          Hasta:{" "}
          <span className="text-base font-semibold">
            {currencyCLP.format(value)}
          </span>
        </span>
        <span className="text-xs text-emerald-800">
          Mín: {currencyCLP.format(0)}
        </span>
      </div>
      {/* Slider */}
      <input
        type="range"
        name="maxPrice"
        min={0}
        max={maxLimit}
        step={1000}
        value={value}
        onChange={(e) => setValue(Number(e.target.value))}
        className="w-full cursor-pointer accent-emerald-600"
      />
      {/* Límites visuales */}
      <div className="flex justify-between text-xs text-emerald-800">
        <span>{currencyCLP.format(0)}</span>
        <span>{currencyCLP.format(maxLimit)}</span>
      </div>
    </div>
  );
}// web/components/cart/cartContext.tsx
"use client";
import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import type { CartItem, Product, CartResponse } from "../../lib/types";
import {
  addToCart as addToCartApi,
  getCart as getCartApi,
  removeFromCart as removeFromCartApi,
  clearCart as clearCartApi,
  updateCartItemQuantity as updateCartItemQuantityApi,
} from "../../lib/cartApi";
import { useAuth } from "../../contexts/AuthContext";
type NotificationType = "success" | "info" | "error";
type CartNotification = {
  message: string;
  type: NotificationType;
} | null;
type CartContextValue = {
  items: CartItem[];
  totalQuantity: number;
  subtotal: number;
  taxes: number;
  totalAmount: number;
  isLoading: boolean;
  addItem: (product: Product, quantity?: number) => Promise<void>;
  updateItemQuantity: (productId: number, quantity: number) => Promise<void>;
  removeItem: (productId: number) => Promise<void>;
  clear: () => Promise<void>;
  refreshCart: () => Promise<void>;
};
const CartContext = createContext<CartContextValue | undefined>(undefined);
export function CartProvider({ children }: { children: ReactNode }) {
  const [cartData, setCartData] = useState<CartResponse>({
    items: [],
    subtotal: 0,
    taxes: 0,
    total: 0,
  });
  const [isLoading, setIsLoading] = useState(false);
  const [notification, setNotification] = useState<CartNotification>(null);
  const { user } = useAuth();
  // Cargar carrito al montar y cuando cambia el usuario
  useEffect(() => {
    loadCart();
  }, [user]);
  const loadCart = async () => {
    try {
      setIsLoading(true);
      const cart = await getCartApi();
      setCartData(cart);
    } catch (error) {
      console.error("Error loading cart:", error);
      // En caso de error, mantener carrito vacío
      setCartData({
        items: [],
        subtotal: 0,
        taxes: 0,
        total: 0,
      });
    } finally {
      setIsLoading(false);
    }
  };
  const showNotification = (message: string, type: NotificationType) => {
    setNotification({ message, type });
    // Ocultar después de 1.5s
    setTimeout(() => {
      setNotification((current) =>
        current?.message === message ? null : current
      );
    }, 1500);
  };
  const addItem = async (product: Product, quantity = 1) => {
    try {
      setIsLoading(true);
      const updatedCart = await addToCartApi(product.id, quantity);
      setCartData(updatedCart);
      showNotification("Producto agregado al carrito", "success");
    } catch (error: any) {
      console.error("Error adding item:", error);
      showNotification(
        error.message || "Error al agregar producto",
        "error"
      );
    } finally {
      setIsLoading(false);
    }
  };
  const updateItemQuantity = async (productId: number, quantity: number) => {
    try {
      setIsLoading(true);
      const updatedCart = await updateCartItemQuantityApi(productId, quantity);
      setCartData(updatedCart);
      showNotification("Cantidad actualizada", "info");
    } catch (error: any) {
      console.error("Error updating quantity:", error);
      showNotification(
        error.message || "Error al actualizar cantidad",
        "error"
      );
    } finally {
      setIsLoading(false);
    }
  };
  const removeItem = async (productId: number) => {
    try {
      setIsLoading(true);
      const updatedCart = await removeFromCartApi(productId);
      setCartData(updatedCart);
      showNotification("Producto eliminado del carrito", "info");
    } catch (error: any) {
      console.error("Error removing item:", error);
      showNotification(
        error.message || "Error al eliminar producto",
        "error"
      );
    } finally {
      setIsLoading(false);
    }
  };
  const clear = async () => {
    try {
      setIsLoading(true);
      await clearCartApi();
      setCartData({
        items: [],
        subtotal: 0,
        taxes: 0,
        total: 0,
      });
      showNotification("Carrito vaciado", "info");
    } catch (error: any) {
      console.error("Error clearing cart:", error);
      showNotification(
        error.message || "Error al vaciar carrito",
        "error"
      );
    } finally {
      setIsLoading(false);
    }
  };
  const refreshCart = async () => {
    await loadCart();
  };
  // Calcular cantidad total de items
  const totalQuantity = cartData.items.reduce(
    (sum, item) => sum + item.quantity,
    0
  );
  const value: CartContextValue = {
    items: cartData.items,
    totalQuantity,
    subtotal: cartData.subtotal,
    taxes: cartData.taxes,
    totalAmount: cartData.total,
    isLoading,
    addItem,
    updateItemQuantity,
    removeItem,
    clear,
    refreshCart,
  };
  return (
    <CartContext.Provider value={value}>
      {children}
      {/* Toast de notificación del carrito */}
      {notification && (
        <div className="pointer-events-none fixed top-20 right-4 z-[9999] flex max-w-xs animate-fade-slide">
          <div
            className={`
              pointer-events-auto rounded-xl border backdrop-blur-md px-4 py-3 shadow-xl
              flex items-center gap-3 text-sm font-medium text-white
              transition-all duration-300
              ${notification.type === "success" &&
              "bg-gradient-to-r from-emerald-600/90 to-emerald-500/90 border-emerald-400/40"
              }
              ${notification.type === "info" &&
              "bg-gradient-to-r from-sky-600/90 to-sky-500/90 border-sky-400/40"
              }
              ${notification.type === "error" &&
              "bg-gradient-to-r from-rose-600/90 to-rose-500/90 border-rose-400/40"
              }
            `}
          >
            {/* Icono según tipo */}
            <span className="text-xl">
              {notification.type === "success" && "✔"}
              {notification.type === "info" && "ℹ"}
              {notification.type === "error" && "✖"}
            </span>
            <span>{notification.message}</span>
          </div>
        </div>
      )}
    </CartContext.Provider>
  );
}
export function useCart(): CartContextValue {
  const ctx = useContext(CartContext);
  if (!ctx) {
    throw new Error("useCart debe usarse dentro de CartProvider");
  }
  return ctx;
