    // No lances un error, simplemente devuelve el usuario si existe, o undefined si no.
    return user;
  }
}import { Test, TestingModule } from '@nestjs/testing';
import { Reflector } from '@nestjs/core';
import { ExecutionContext } from '@nestjs/common';
import { RolesGuard } from './roles.guard';
import { Role } from '../models/roles.model';
describe('RolesGuard', () => {
  let guard: RolesGuard;
  let reflector: Reflector;
  const mockReflector = {
    getAllAndOverride: jest.fn(),
  };
  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        RolesGuard,
        {
          provide: Reflector,
          useValue: mockReflector,
        },
      ],
    }).compile();
    guard = module.get<RolesGuard>(RolesGuard);
    reflector = module.get<Reflector>(Reflector);
    jest.clearAllMocks();
  });
  it('should be defined', () => {
    expect(guard).toBeDefined();
  });
  describe('canActivate', () => {
    const createMockExecutionContext = (user: any): ExecutionContext => {
      return {
        switchToHttp: () => ({
          getRequest: () => ({
            user,
          }),
        }),
        getHandler: jest.fn(),
        getClass: jest.fn(),
      } as any;
    };
    it('should allow access when no roles are required', () => {
      mockReflector.getAllAndOverride.mockReturnValue(undefined);
      const context = createMockExecutionContext({ id: 1, roles: [] });
      const result = guard.canActivate(context);
      expect(result).toBe(true);
    });
    it('should allow access when user has required role (admin)', () => {
      mockReflector.getAllAndOverride.mockReturnValue([Role.ADMIN]);
      const context = createMockExecutionContext({
        id: 1,
        roles: [Role.ADMIN],
      });
      const result = guard.canActivate(context);
      expect(result).toBe(true);
    });
    it('should allow access when user has required role (user)', () => {
      mockReflector.getAllAndOverride.mockReturnValue([Role.USER]);
      const context = createMockExecutionContext({
        id: 1,
        roles: [Role.USER],
      });
      const result = guard.canActivate(context);
      expect(result).toBe(true);
    });
    it('should deny access when user does not have required role', () => {
      mockReflector.getAllAndOverride.mockReturnValue([Role.ADMIN]);
      const context = createMockExecutionContext({
        id: 1,
        roles: [Role.USER],
      });
      const result = guard.canActivate(context);
      expect(result).toBe(false);
    });
    it('should deny access when user has no roles', () => {
      mockReflector.getAllAndOverride.mockReturnValue([Role.ADMIN]);
      const context = createMockExecutionContext({
        id: 1,
        roles: [],
      });
      const result = guard.canActivate(context);
      expect(result).toBe(false);
    });
    it('should deny access when user is not authenticated', () => {
      mockReflector.getAllAndOverride.mockReturnValue([Role.ADMIN]);
      const context = createMockExecutionContext(null);
      const result = guard.canActivate(context);
      expect(result).toBe(false);
    });
    it('should allow access when user has multiple roles including required one', () => {
      mockReflector.getAllAndOverride.mockReturnValue([Role.ADMIN]);
      const context = createMockExecutionContext({
        id: 1,
        roles: [Role.USER, Role.ADMIN],
      });
      const result = guard.canActivate(context);
      expect(result).toBe(true);
    });
    it('should handle multiple required roles correctly', () => {
      mockReflector.getAllAndOverride.mockReturnValue([Role.ADMIN, Role.USER]);
      const context = createMockExecutionContext({
        id: 1,
        roles: [Role.USER],
      });
      const result = guard.canActivate(context);
      expect(result).toBe(true);
    });
  });
});import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';
import { Role } from '../models/roles.model';
@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}
  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (!requiredRoles) {
      return true;
    }
    const { user } = context.switchToHttp().getRequest();
    if (!user) {
      return false;
    }
    return requiredRoles.some((role) => user.roles?.includes(role));
  }
}import { Role } from '../models/roles.model';
export interface JwtPayload {
  sub: number; // ID del usuario (estándar JWT usa 'sub' para subject)
  email: string;
  roles: Role[];
}export enum Role {
  ADMIN = 'admin',
  USER = 'user',
}import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { ConfigService } from '@nestjs/config';
