        slug: 'test',
        price: 1000,
        stock: 10,
        categoryId: 1,
      });
      const errors = await validate(dto);
      expect(errors.length).toBeGreaterThan(0);
      expect(errors[0].property).toBe('name');
    });
    it('should fail validation when price is negative', async () => {
