export * from './pagination.dto';import { IsOptional, IsInt, Min, Max, IsString } from 'class-validator';
import { Type } from 'class-transformer';
import { ApiProperty } from '@nestjs/swagger';
export class PaginationDto {
  @ApiProperty({
    description: 'Page number (1-based)',
    minimum: 1,
    default: 1,
    required: false,
    example: 1,
  })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page?: number = 1;
  @ApiProperty({
    description: 'Number of items per page',
    minimum: 1,
    maximum: 100,
    default: 20,
    required: false,
    example: 20,
  })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  limit?: number = 20;
  @ApiProperty({
    description: 'Search term to filter products by name (case-insensitive)',
    required: false,
    example: 'laptop',
  })
  @IsOptional()
  @IsString()
  search?: string;
  @ApiProperty({
    description: 'Filter products by category ID',
    minimum: 1,
    required: false,
    example: 1,
  })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  categoryId?: number;
}
export interface PaginatedResponse<T> {
  items: T[];
  total: number;
  page: number;
  lastPage: number;
  hasMore: boolean;
}
export interface ProductFilters {
  search?: string;
  categoryId?: number;
}import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  ManyToOne,
  JoinColumn,
  Index,
  CreateDateColumn,
  UpdateDateColumn,
} from 'typeorm';
import { Category } from './category.entity';
@Entity({ name: 'products' })
@Index('idx_products_category_name', ['category', 'name'])
@Index('idx_products_name_search', ['name'])
@Index('idx_products_created_at', ['createdAt'])
@Index('idx_products_price', ['price'])
export class Product {
  @PrimaryGeneratedColumn()
  id: number;
  @Column({ type: 'varchar', length: 255 })
  name: string;
  @Column({ type: 'varchar', length: 255, unique: true })
  slug: string;
  @Column({ type: 'text' })
  description: string;
  @Column({ type: 'decimal', precision: 10, scale: 2 })
  price: number;
  @Column({ type: 'int' })
  stock: number;
  @Column({ type: 'varchar', name: 'image_url', nullable: true })
  imageUrl: string;
  // --- NUEVOS CAMPOS PARA OFERTAS / CARRUSEL ---
  @Column({ type: 'boolean', name: 'is_featured', default: false })
  isFeatured: boolean;
  @Column({ type: 'boolean', name: 'is_on_sale', default: false })
  isOnSale: boolean;
  @Column({ type: 'int', name: 'discount_percent', nullable: true })
  discountPercent: number | null;
  // Timestamps for ordering and tracking
  @CreateDateColumn({ name: 'created_at' })
  createdAt: Date;
  @UpdateDateColumn({ name: 'updated_at' })
  updatedAt: Date;
  // Relación con categoría
  @ManyToOne(() => Category, (category) => category.products, {
    onDelete: 'SET NULL',
    nullable: true,
  })
  @JoinColumn({ name: 'category_id' })
  category: Category | null;
}export * from './paginated-response.interface';
export * from './product-filters.interface';export interface PaginatedResponse<T> {
  items: T[];
  total: number;
  page: number;
  lastPage: number;
  hasMore: boolean;
}export interface ProductFilters {
  search?: string;
  categoryId?: number;
  minPrice?: number;
  maxPrice?: number;
}import {
  Controller,
  Get,
  Post,
  Body,
  Param,
  Delete,
  Put,
  ParseIntPipe,
  HttpCode,
  HttpStatus,
  Query,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiQuery,
  ApiParam,
  ApiBody,
} from '@nestjs/swagger';
import { ProductsService } from './products.service';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
import { PaginationDto } from './dto/pagination.dto';
@ApiTags('Products')
@Controller('products')
export class ProductsController {
  constructor(private readonly productsService: ProductsService) {}
  @Post()
  @ApiOperation({
    summary: 'Create a new product',
    description: 'Create a new product. Admin authentication required.',
  })
  @ApiBody({ type: CreateProductDto })
  @ApiResponse({
    status: 201,
    description: 'Product successfully created',
  })
  @ApiResponse({
    status: 400,
    description: 'Bad request - validation failed',
  })
  @ApiResponse({
    status: 404,
    description: 'Category not found',
  })
  create(@Body() createProductDto: CreateProductDto) {
    return this.productsService.create(createProductDto);
  }
  @Get()
  @ApiOperation({
    summary: 'Get all products',
    description:
      'Retrieve all products without pagination. Use /paginated endpoint for better performance with large datasets.',
  })
  @ApiResponse({
    status: 200,
    description: 'Successfully retrieved all products',
  })
  findAll() {
    return this.productsService.findAll();
  }
  @Get('paginated')
  @ApiOperation({
    summary: 'Get paginated products',
    description:
      'Retrieve products with server-side pagination and optional filtering by search term and category. Supports efficient loading of large product catalogs.',
  })
  @ApiQuery({
    name: 'page',
    required: false,
    type: Number,
    description: 'Page number (1-based)',
    example: 1,
  })
  @ApiQuery({
    name: 'limit',
    required: false,
    type: Number,
    description: 'Number of items per page (max: 100)',
    example: 20,
  })
  @ApiQuery({
    name: 'search',
    required: false,
    type: String,
    description: 'Search term to filter products by name (case-insensitive)',
    example: 'laptop',
  })
  @ApiQuery({
    name: 'categoryId',
    required: false,
    type: Number,
    description: 'Filter products by category ID',
    example: 1,
  })
  @ApiResponse({
    status: 200,
    description: 'Successfully retrieved paginated products',
    schema: {
      type: 'object',
      properties: {
        items: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              id: { type: 'number', example: 1 },
              name: { type: 'string', example: 'Gaming Laptop Pro' },
              slug: { type: 'string', example: 'gaming-laptop-pro' },
              description: {
                type: 'string',
                example: 'High-performance gaming laptop',
              },
              price: { type: 'number', example: 1299.99 },
              stock: { type: 'number', example: 15 },
              imageUrl: {
                type: 'string',
                example: 'https://example.com/image.jpg',
              },
              isFeatured: { type: 'boolean', example: true },
              isOnSale: { type: 'boolean', example: false },
              discountPercent: {
                type: 'number',
                nullable: true,
                example: null,
              },
              category: {
                type: 'object',
                properties: {
                  id: { type: 'number', example: 1 },
                  name: { type: 'string', example: 'Laptops' },
                  slug: { type: 'string', example: 'laptops' },
                },
              },
            },
          },
        },
        total: {
          type: 'number',
          example: 150,
          description: 'Total number of products matching filters',
        },
        page: {
          type: 'number',
          example: 1,
          description: 'Current page number',
        },
        lastPage: {
          type: 'number',
          example: 8,
          description: 'Last page number',
        },
        hasMore: {
          type: 'boolean',
          example: true,
          description: 'Whether more pages are available',
        },
      },
    },
  })
  @ApiResponse({
    status: 400,
    description: 'Bad request - invalid query parameters',
    schema: {
      type: 'object',
      properties: {
        statusCode: { type: 'number', example: 400 },
        message: {
          type: 'array',
          items: { type: 'string' },
          example: [
            'page must not be less than 1',
            'limit must not be greater than 100',
          ],
        },
        error: { type: 'string', example: 'Bad Request' },
      },
    },
  })
  @ApiResponse({
    status: 500,
    description: 'Internal server error',
  })
  async findAllPaginated(@Query() paginationDto: PaginationDto) {
    const { page = 1, limit = 20, search, categoryId } = paginationDto;
    const filters = {
      ...(search && { search }),
      ...(categoryId && { categoryId }),
    };
    return this.productsService.findAllPaginated(page, limit, filters);
  }
  @Get(':id')
  @ApiOperation({
    summary: 'Get product by ID',
    description: 'Retrieve a single product by its ID',
  })
  @ApiParam({
    name: 'id',
    type: Number,
    description: 'Product ID',
    example: 1,
  })
  @ApiResponse({
    status: 200,
    description: 'Successfully retrieved product',
  })
  @ApiResponse({
    status: 404,
    description: 'Product not found',
  })
  findOne(@Param('id', ParseIntPipe) id: number) {
    return this.productsService.findOne(id);
  }
  @Put(':id')
  @ApiOperation({
    summary: 'Update product',
    description: 'Update an existing product. Admin authentication required.',
  })
  @ApiParam({
    name: 'id',
    type: Number,
    description: 'Product ID',
    example: 1,
  })
  @ApiBody({ type: UpdateProductDto })
  @ApiResponse({
    status: 200,
    description: 'Product successfully updated',
  })
  @ApiResponse({
    status: 404,
    description: 'Product not found',
  })
  update(
    @Param('id', ParseIntPipe) id: number,
    @Body() updateProductDto: UpdateProductDto,
  ) {
    return this.productsService.update(id, updateProductDto);
  }
  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({
    summary: 'Delete product',
    description: 'Delete a product by ID. Admin authentication required.',
  })
  @ApiParam({
    name: 'id',
    type: Number,
    description: 'Product ID',
    example: 1,
  })
  @ApiResponse({
    status: 204,
    description: 'Product successfully deleted',
  })
  @ApiResponse({
    status: 404,
    description: 'Product not found',
  })
  remove(@Param('id', ParseIntPipe) id: number) {
    return this.productsService.remove(id);
  }
}import { Test, TestingModule } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import {
  NotFoundException,
  InternalServerErrorException,
} from '@nestjs/common';
import { ProductsService } from './products.service';
import { Product } from './entities/product.entity';
import { Category } from './entities/category.entity';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
describe('ProductsService', () => {
  let service: ProductsService;
  let productRepository: Repository<Product>;
  let categoryRepository: Repository<Category>;
  const mockProductRepository = {
    create: jest.fn(),
    save: jest.fn(),
    find: jest.fn(),
    findOne: jest.fn(),
    findOneBy: jest.fn(),
    preload: jest.fn(),
    delete: jest.fn(),
    remove: jest.fn(),
  };
  const mockCategoryRepository = {
    findOne: jest.fn(),
    findOneBy: jest.fn(),
  };
  const mockCategory: Category = {
    id: 1,
    name: 'Limpieza',
    slug: 'limpieza',
    products: [],
    generateSlugOnInsert: jest.fn(),
    generateSlugOnUpdate: jest.fn(),
  };
  const mockProduct: Product = {
    id: 1,
    name: 'Cloro 1L',
    description: 'Cloro líquido para limpieza',
    slug: 'cloro-1l',
    price: 2990,
    stock: 100,
    imageUrl: 'http://localhost:9000/products/cloro.jpg',
    category: mockCategory,
    isFeatured: false,
    isOnSale: false,
    discountPercent: null,
    createdAt: new Date(),
    updatedAt: new Date(),
  };
  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        ProductsService,
        {
          provide: getRepositoryToken(Product),
          useValue: mockProductRepository,
        },
        {
          provide: getRepositoryToken(Category),
          useValue: mockCategoryRepository,
        },
      ],
    }).compile();
    service = module.get<ProductsService>(ProductsService);
    productRepository = module.get<Repository<Product>>(
      getRepositoryToken(Product),
    );
    categoryRepository = module.get<Repository<Category>>(
      getRepositoryToken(Category),
    );
    // Limpiar mocks antes de cada test
    jest.clearAllMocks();
  });
  it('should be defined', () => {
    expect(service).toBeDefined();
  });
  describe('create', () => {
    const createProductDto: CreateProductDto = {
      name: 'Cloro 1L',
      description: 'Cloro líquido para limpieza',
      slug: 'cloro-1l',
      price: 2990,
      stock: 100,
      imageUrl: 'http://localhost:9000/products/cloro.jpg',
      categoryId: 1,
      isFeatured: false,
      isOnSale: false,
      discountPercent: 0,
    };
    it('should create a product successfully', async () => {
      mockCategoryRepository.findOneBy.mockResolvedValue(mockCategory);
      mockProductRepository.create.mockReturnValue(mockProduct);
      mockProductRepository.save.mockResolvedValue(mockProduct);
      const result = await service.create(createProductDto);
      expect(categoryRepository.findOneBy).toHaveBeenCalledWith({
        id: createProductDto.categoryId,
      });
      expect(productRepository.create).toHaveBeenCalled();
      expect(productRepository.save).toHaveBeenCalledWith(mockProduct);
      expect(result).toEqual(mockProduct);
    });
    it('should throw NotFoundException when category does not exist', async () => {
      mockCategoryRepository.findOneBy.mockResolvedValue(null);
      await expect(service.create(createProductDto)).rejects.toThrow(
        NotFoundException,
      );
      await expect(service.create(createProductDto)).rejects.toThrow(
        `Category with ID "${createProductDto.categoryId}" not found`,
      );
    });
    it('should create product with default image if none provided', async () => {
      const dtoWithoutImage = { ...createProductDto, imageUrl: undefined };
      const productWithDefaultImage = {
        ...mockProduct,
        imageUrl: undefined,
      };
      mockCategoryRepository.findOneBy.mockResolvedValue(mockCategory);
      mockProductRepository.create.mockReturnValue(productWithDefaultImage);
      mockProductRepository.save.mockResolvedValue(productWithDefaultImage);
      const result = await service.create(dtoWithoutImage);
      expect(mockCategoryRepository.findOneBy).toHaveBeenCalled();
      expect(mockProductRepository.create).toHaveBeenCalled();
    });
    it('should throw InternalServerErrorException on database error', async () => {
      mockCategoryRepository.findOneBy.mockResolvedValue(mockCategory);
      mockProductRepository.create.mockReturnValue(mockProduct);
      mockProductRepository.save.mockRejectedValue(
        new Error('Database connection failed'),
      );
      await expect(service.create(createProductDto)).rejects.toThrow(Error);
    });
  });
  describe('findAll', () => {
    it('should return an array of products', async () => {
      const mockProducts = [mockProduct];
      mockProductRepository.find.mockResolvedValue(mockProducts);
      const result = await service.findAll();
      expect(productRepository.find).toHaveBeenCalledWith({
        relations: ['category'],
      });
      expect(result).toEqual(mockProducts);
    });
    it('should return empty array when no products exist', async () => {
      mockProductRepository.find.mockResolvedValue([]);
      const result = await service.findAll();
      expect(result).toEqual([]);
      expect(result).toHaveLength(0);
    });
    it('should throw InternalServerErrorException on database error', async () => {
      mockProductRepository.find.mockRejectedValue(new Error('Database error'));
      await expect(service.findAll()).rejects.toThrow(Error);
    });
  });
  describe('findOne', () => {
    it('should return a product by id', async () => {
      mockProductRepository.findOne.mockResolvedValue(mockProduct);
      const result = await service.findOne(1);
      expect(productRepository.findOne).toHaveBeenCalledWith({
        where: { id: 1 },
        relations: ['category'],
      });
      expect(result).toEqual(mockProduct);
    });
    it('should throw NotFoundException when product does not exist', async () => {
      mockProductRepository.findOne.mockResolvedValue(null);
      await expect(service.findOne(999)).rejects.toThrow(NotFoundException);
      await expect(service.findOne(999)).rejects.toThrow(
        'Product with ID "999" not found',
      );
    });
  });
  describe('update', () => {
    const updateProductDto: UpdateProductDto = {
      name: 'Cloro 2L',
      price: 4990,
    };
    it('should update a product successfully', async () => {
      const updatedProduct = { ...mockProduct, ...updateProductDto };
      mockProductRepository.preload.mockResolvedValue(updatedProduct);
      mockProductRepository.save.mockResolvedValue(updatedProduct);
      const result = await service.update(1, updateProductDto);
      expect(productRepository.preload).toHaveBeenCalledWith({
        id: 1,
        ...updateProductDto,
      });
      expect(productRepository.save).toHaveBeenCalled();
      expect(result.name).toEqual(updateProductDto.name);
      expect(result.price).toEqual(updateProductDto.price);
    });
    it('should throw NotFoundException when product does not exist', async () => {
      mockProductRepository.preload.mockResolvedValue(null);
      await expect(service.update(999, updateProductDto)).rejects.toThrow(
        NotFoundException,
      );
    });
    it('should update category when categoryId is provided', async () => {
      const updateWithCategory = { ...updateProductDto, categoryId: 2 };
      const newCategory = { ...mockCategory, id: 2, name: 'Desinfectantes' };
      const productWithNewCategory = { ...mockProduct, category: newCategory };
      mockProductRepository.preload.mockResolvedValue(mockProduct);
      mockCategoryRepository.findOneBy.mockResolvedValue(newCategory);
      mockProductRepository.save.mockResolvedValue(productWithNewCategory);
      const result = await service.update(1, updateWithCategory);
      expect(categoryRepository.findOneBy).toHaveBeenCalledWith({
        id: 2,
      });
      expect(result.category?.id).toEqual(2);
    });
    it('should throw NotFoundException when new category does not exist', async () => {
      const updateWithCategory = { ...updateProductDto, categoryId: 999 };
      mockProductRepository.preload.mockResolvedValue(mockProduct);
      mockCategoryRepository.findOneBy.mockResolvedValue(null);
      await expect(service.update(1, updateWithCategory)).rejects.toThrow(
        NotFoundException,
      );
    });
  });
  describe('remove', () => {
    it('should remove a product successfully', async () => {
      mockProductRepository.delete.mockResolvedValue({ affected: 1, raw: {} });
      await service.remove(1);
      expect(productRepository.delete).toHaveBeenCalledWith(1);
    });
    it('should throw NotFoundException when product does not exist', async () => {
      mockProductRepository.delete.mockResolvedValue({ affected: 0, raw: {} });
      await expect(service.remove(999)).rejects.toThrow(NotFoundException);
      await expect(service.remove(999)).rejects.toThrow(
        'Product with ID "999" not found',
      );
    });
    it('should throw InternalServerErrorException on database error', async () => {
      mockProductRepository.delete.mockRejectedValue(
        new Error('Database error'),
      );
      await expect(service.remove(1)).rejects.toThrow(Error);
    });
  });
});import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
import { PaginatedResponse, ProductFilters } from './dto/pagination.dto';
import { Product } from './entities/product.entity';
import { Category } from './entities/category.entity';
@Injectable()
export class ProductsService {
  constructor(
    @InjectRepository(Product)
    private readonly productRepository: Repository<Product>,
    @InjectRepository(Category)
    private readonly categoryRepository: Repository<Category>,
  ) {}
  async create(createProductDto: CreateProductDto): Promise<Product> {
    const { categoryId, ...productData } = createProductDto;
    const category = await this.categoryRepository.findOneBy({
      id: categoryId,
    });
    if (!category) {
      throw new NotFoundException(`Category with ID "${categoryId}" not found`);
    }
    const product = this.productRepository.create({
      ...productData,
      category,
    });
    return this.productRepository.save(product);
  }
  findAll(): Promise<Product[]> {
    return this.productRepository.find({
      relations: ['category'],
    });
  }
  async findAllPaginated(
    page: number = 1,
    limit: number = 20,
    filters?: ProductFilters,
  ): Promise<PaginatedResponse<Product>> {
    const queryBuilder = this.productRepository
      .createQueryBuilder('product')
      .leftJoinAndSelect('product.category', 'category')
      .orderBy('product.id', 'DESC');
    // Apply search filter
    if (filters?.search) {
      queryBuilder.andWhere('product.name ILIKE :search', {
        search: `%${filters.search}%`,
      });
    }
    // Apply category filter
    if (filters?.categoryId) {
      queryBuilder.andWhere('product.category.id = :categoryId', {
        categoryId: filters.categoryId,
      });
    }
    // Calculate offset
    const offset = (page - 1) * limit;
    // Get total count
    const total = await queryBuilder.getCount();
    // Get paginated results
    const items = await queryBuilder.skip(offset).take(limit).getMany();
    // Calculate pagination metadata
    const lastPage = Math.ceil(total / limit);
    const hasMore = page < lastPage;
    return {
      items,
      total,
      page,
      lastPage,
      hasMore,
    };
  }
  async findOne(id: number): Promise<Product> {
    const product = await this.productRepository.findOne({
      where: { id },
      relations: ['category'],
    });
    if (!product) {
      throw new NotFoundException(`Product with ID "${id}" not found`);
    }
    return product;
  }
  async update(
    id: number,
    updateProductDto: UpdateProductDto,
  ): Promise<Product> {
    const product = await this.productRepository.preload({
      id: id,
      ...updateProductDto,
    });
    if (!product) {
      throw new NotFoundException(`Product with ID "${id}" not found`);
    }
    // Si se incluye categoryId en la actualización, buscar y asignar la categoría correspondiente
    if (updateProductDto.categoryId) {
      const category = await this.categoryRepository.findOneBy({
        id: updateProductDto.categoryId,
      });
      if (!category) {
        throw new NotFoundException(
          `Category with ID "${updateProductDto.categoryId}" not found`,
        );
      }
      product.category = category;
    }
    return this.productRepository.save(product);
  }
  async remove(id: number): Promise<void> {
    const result = await this.productRepository.delete(id);
    if (result.affected === 0) {
      throw new NotFoundException(`Product with ID "${id}" not found`);
    }
  }
}import { Injectable } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bull';
import type { Queue } from 'bull';
import { Redis } from 'ioredis';
@Injectable()
export class RedisService {
  private readonly redisClient: Redis;
  constructor(@InjectQueue('redis-queue') queue: Queue) {
    this.redisClient = queue.client;
  }
  async get(key: string): Promise<string | null> {
    return this.redisClient.get(key);
  }
  async set(key: string, value: string, ttl?: number): Promise<void> {
    if (ttl) {
      await this.redisClient.set(key, value, 'EX', ttl);
    } else {
      await this.redisClient.set(key, value);
    }
  }
  async del(key: string): Promise<void> {
    await this.redisClient.del(key);
  }
