 * Media API Client
 * Handles image upload, list, and delete operations with MinIO storage
 */
import { getAccessToken } from './apiClient';
const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3002';
/**
 * Response type for image upload
 */
export type UploadResponse = {
    url: string;
};
/**
 * Response type for image list
 */
export type ListResponse = string[];
/**
 * Response type for image deletion
 */
export type DeleteResponse = {
    success: boolean;
};
/**
 * Upload an image file to MinIO storage
 * POST /media/upload
 * 
 * @param file - The image file to upload
 * @returns Promise with the uploaded image URL
 * @throws Error if upload fails
 */
export async function uploadImage(file: File): Promise<{ url: string }> {
    try {
        // Create FormData with the file
        const formData = new FormData();
        formData.append('file', file);
        // Get access token for authentication
        const accessToken = getAccessToken();
        // Prepare headers (don't set Content-Type for FormData - browser will set it with boundary)
        const headers: Record<string, string> = {};
        if (accessToken) {
            headers['Authorization'] = `Bearer ${accessToken}`;
        }
        // Make POST request to upload endpoint
        const response = await fetch(`${API_BASE_URL}/media/upload`, {
            method: 'POST',
            headers,
            body: formData,
            credentials: 'include',
        });
        // Handle upload errors
        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `Upload failed with status ${response.status}`);
        }
        // Parse and return the response with URL
        const data: UploadResponse = await response.json();
        return { url: data.url };
    } catch (error: any) {
        console.error('Error uploading image:', error);
        throw new Error(error.message || 'Failed to upload image');
    }
}
/**
 * Upload multiple image files to MinIO storage
 * POST /media/upload-multiple
 * 
 * @param files - Array of image files to upload
 * @returns Promise with array of uploaded image URLs
 * @throws Error if upload fails
 */
export async function uploadImages(files: File[]): Promise<{ urls: string[] }> {
    try {
        // Create FormData with all files
        const formData = new FormData();
        files.forEach((file) => {
            formData.append('files', file);
        });
        // Get access token for authentication
        const accessToken = getAccessToken();
        // Prepare headers (don't set Content-Type for FormData - browser will set it with boundary)
        const headers: Record<string, string> = {};
        if (accessToken) {
            headers['Authorization'] = `Bearer ${accessToken}`;
        }
        // Make POST request to upload-multiple endpoint
        const response = await fetch(`${API_BASE_URL}/media/upload-multiple`, {
            method: 'POST',
            headers,
            body: formData,
            credentials: 'include',
        });
        // Handle upload errors
        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `Upload failed with status ${response.status}`);
        }
        // Parse and return the response with URLs
        const data: { urls: string[] } = await response.json();
        return { urls: data.urls };
    } catch (error: any) {
        console.error('Error uploading images:', error);
        throw new Error(error.message || 'Failed to upload images');
    }
}
/**
 * Get list of all uploaded images
 * GET /media/list
 * 
 * @returns Promise with array of image URLs
 * @throws Error if fetching fails
 */
export async function listImages(): Promise<string[]> {
    try {
        // Get access token for authentication
        const accessToken = getAccessToken();
        // Prepare headers
        const headers: Record<string, string> = {
            'Content-Type': 'application/json',
        };
        if (accessToken) {
            headers['Authorization'] = `Bearer ${accessToken}`;
        }
        // Make GET request to list endpoint
        const response = await fetch(`${API_BASE_URL}/media/list`, {
            method: 'GET',
            headers,
            credentials: 'include',
        });
        // Handle network errors
        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `Failed to fetch images with status ${response.status}`);
        }
        // Parse and return array of URLs
        const data: ListResponse = await response.json();
        return data;
    } catch (error: any) {
        console.error('Error fetching image list:', error);
        throw new Error(error.message || 'Failed to fetch image list');
    }
}
/**
 * Extract filename from full URL
 * Helper function for delete operation
 * 
 * @param url - Full URL of the image
 * @returns Filename extracted from URL
 */
function extractFilename(url: string): string {
    try {
        // Extract filename from URL (last segment after /)
        const urlParts = url.split('/');
        const filename = urlParts[urlParts.length - 1];
        // Remove query parameters if present
        return filename.split('?')[0];
    } catch (error) {
        console.error('Error extracting filename from URL:', error);
        throw new Error('Invalid URL format');
    }
}
/**
 * Delete an image from storage
 * DELETE /media?file=<filename>
 * 
 * @param url - Full URL of the image to delete
 * @returns Promise with success boolean
 * @throws Error if deletion fails
 */
export async function deleteImage(url: string): Promise<boolean> {
    try {
        // Extract filename from URL
        const filename = extractFilename(url);
        // Get access token for authentication
        const accessToken = getAccessToken();
        // Prepare headers
        const headers: Record<string, string> = {
            'Content-Type': 'application/json',
        };
        if (accessToken) {
            headers['Authorization'] = `Bearer ${accessToken}`;
        }
        // Make DELETE request to delete endpoint
        const response = await fetch(`${API_BASE_URL}/media?file=${encodeURIComponent(filename)}`, {
            method: 'DELETE',
            headers,
            credentials: 'include',
        });
        // Handle delete errors
        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `Failed to delete image with status ${response.status}`);
        }
        // Parse and return success status
        const data: DeleteResponse = await response.json();
        return data.success;
    } catch (error: any) {
        console.error('Error deleting image:', error);
        throw new Error(error.message || 'Failed to delete image');
    }
}// web/lib/paymentsApi.ts
import { api } from "./apiClient";
/**
 * Crea una transacción de pago en Webpay Plus (soporta invitados)
 */
export async function createWebpayTransaction(orderId: number): Promise<{
    url: string;
    token: string;
}> {
    const result = await api.post<
        | { success: true; data: { url: string; token: string } }
        | { url: string; token: string }
    >(
        '/payments/webpay/create',
        { orderId }
    );
    if ('data' in result && result.data) {
        return result.data;
    }
    return result;
}
/**
 * Confirma una transacción de Webpay Plus
 */
export async function commitWebpayPayment(token_ws: string): Promise<{
    status: string;
    orderId: number;
    amount: number;
    authorizationCode?: string;
    paymentTypeCode?: string;
}> {
    const result = await api.post<
        | {
            success: true;
            data: {
                status: string;
                orderId: number;
                amount: number;
                authorizationCode?: string;
                paymentTypeCode?: string;
            };
        }
        | {
            status: string;
            orderId: number;
            amount: number;
            authorizationCode?: string;
            paymentTypeCode?: string;
        }
    >(
        '/payments/webpay/commit',
        { token_ws }
    );
    if ('data' in result && result.data) {
        return result.data;
    }
    return result;
}/**
 * Performance monitoring utilities for pagination and infinite scroll
 * Requirements: 1.1 - Performance monitoring for load times
 */
export interface PerformanceMetric {
    operation: string;
    duration: number;
    timestamp: number;
    metadata?: Record<string, any>;
}
export interface MemoryMetric {
    operation: string;
    heapUsed: number;
    heapTotal: number;
    timestamp: number;
    itemCount?: number;
}
class PerformanceMonitor {
    private metrics: PerformanceMetric[] = [];
    private memoryMetrics: MemoryMetric[] = [];
    private maxMetrics = 100; // Keep only last 100 metrics
    /**
     * Start timing an operation
     */
    startTiming(operation: string): (metadata?: Record<string, any>) => number {
        const startTime = performance.now();
        return (metadata?: Record<string, any>) => {
            const endTime = performance.now();
            const duration = endTime - startTime;
            this.addMetric({
                operation,
                duration,
                timestamp: Date.now(),
                metadata
            });
            return duration;
        };
    }
    /**
     * Add a performance metric
     */
    addMetric(metric: PerformanceMetric): void {
        this.metrics.push(metric);
        // Keep only the most recent metrics
        if (this.metrics.length > this.maxMetrics) {
            this.metrics = this.metrics.slice(-this.maxMetrics);
        }
        // Log in development
        if (process.env.NODE_ENV === 'development') {
            console.log(`[Performance] ${metric.operation}: ${metric.duration.toFixed(2)}ms`, metric.metadata);
            // Warn about slow operations
            if (metric.duration > 2000) {
                console.warn(`[Performance Warning] Slow operation: ${metric.operation} took ${metric.duration.toFixed(2)}ms`);
            }
        }
    }
    /**
     * Record memory usage for infinite scroll monitoring
     */
    recordMemoryUsage(operation: string, itemCount?: number): void {
        if (typeof window === 'undefined' || !('performance' in window) || !('memory' in (window.performance as any))) {
            return; // Memory API not available
        }
        const memory = (window.performance as any).memory;
        const memoryMetric: MemoryMetric = {
            operation,
            heapUsed: memory.usedJSHeapSize,
            heapTotal: memory.totalJSHeapSize,
            timestamp: Date.now(),
            itemCount
        };
        this.memoryMetrics.push(memoryMetric);
        // Keep only the most recent memory metrics
        if (this.memoryMetrics.length > this.maxMetrics) {
            this.memoryMetrics = this.memoryMetrics.slice(-this.maxMetrics);
        }
        // Log memory usage in development
        if (process.env.NODE_ENV === 'development') {
            const heapUsedMB = (memory.usedJSHeapSize / 1024 / 1024).toFixed(2);
            const heapTotalMB = (memory.totalJSHeapSize / 1024 / 1024).toFixed(2);
            console.log(`[Memory] ${operation}: ${heapUsedMB}MB / ${heapTotalMB}MB (${itemCount} items)`);
        }
    }
    /**
     * Get performance statistics
     */
    getStats(): {
        averageLoadTime: number;
        slowestOperation: PerformanceMetric | null;
        fastestOperation: PerformanceMetric | null;
        totalOperations: number;
        memoryTrend: 'stable' | 'increasing' | 'decreasing' | 'unknown';
    } {
        if (this.metrics.length === 0) {
            return {
                averageLoadTime: 0,
                slowestOperation: null,
                fastestOperation: null,
                totalOperations: 0,
                memoryTrend: 'unknown'
            };
        }
        const durations = this.metrics.map(m => m.duration);
        const averageLoadTime = durations.reduce((sum, d) => sum + d, 0) / durations.length;
        const slowestOperation = this.metrics.reduce((slowest, current) =>
            current.duration > slowest.duration ? current : slowest
        );
        const fastestOperation = this.metrics.reduce((fastest, current) =>
            current.duration < fastest.duration ? current : fastest
        );
        // Analyze memory trend
        let memoryTrend: 'stable' | 'increasing' | 'decreasing' | 'unknown' = 'unknown';
        if (this.memoryMetrics.length >= 3) {
            const recent = this.memoryMetrics.slice(-3);
            const first = recent[0].heapUsed;
            const last = recent[recent.length - 1].heapUsed;
            const diff = last - first;
            const threshold = 1024 * 1024; // 1MB threshold
            if (Math.abs(diff) < threshold) {
                memoryTrend = 'stable';
            } else if (diff > threshold) {
                memoryTrend = 'increasing';
            } else {
                memoryTrend = 'decreasing';
            }
        }
        return {
            averageLoadTime,
            slowestOperation,
            fastestOperation,
            totalOperations: this.metrics.length,
            memoryTrend
        };
    }
    /**
     * Get recent metrics for debugging
     */
    getRecentMetrics(count: number = 10): PerformanceMetric[] {
        return this.metrics.slice(-count);
    }
    /**
     * Get recent memory metrics for debugging
     */
    getRecentMemoryMetrics(count: number = 10): MemoryMetric[] {
        return this.memoryMetrics.slice(-count);
    }
    /**
     * Clear all metrics
     */
    clear(): void {
        this.metrics = [];
        this.memoryMetrics = [];
    }
    /**
     * Check if performance is within acceptable thresholds
     */
    checkPerformanceThresholds(): {
        initialLoadOk: boolean;
        subsequentLoadOk: boolean;
        memoryStable: boolean;
        warnings: string[];
    } {
        const stats = this.getStats();
        const warnings: string[] = [];
        // Check initial load time (should be < 2 seconds)
        const initialLoadMetrics = this.metrics.filter(m => m.operation.includes('initial') || m.metadata?.page === 1);
        const avgInitialLoad = initialLoadMetrics.length > 0
            ? initialLoadMetrics.reduce((sum, m) => sum + m.duration, 0) / initialLoadMetrics.length
            : 0;
        const initialLoadOk = avgInitialLoad < 2000;
        if (!initialLoadOk && avgInitialLoad > 0) {
            warnings.push(`Initial load time is ${avgInitialLoad.toFixed(0)}ms (should be < 2000ms)`);
        }
        // Check subsequent load times (should be < 500ms)
        const subsequentLoadMetrics = this.metrics.filter(m => m.metadata?.page && m.metadata.page > 1);
        const avgSubsequentLoad = subsequentLoadMetrics.length > 0
            ? subsequentLoadMetrics.reduce((sum, m) => sum + m.duration, 0) / subsequentLoadMetrics.length
            : 0;
        const subsequentLoadOk = avgSubsequentLoad < 500;
        if (!subsequentLoadOk && avgSubsequentLoad > 0) {
            warnings.push(`Subsequent load time is ${avgSubsequentLoad.toFixed(0)}ms (should be < 500ms)`);
        }
        // Check memory stability
        const memoryStable = stats.memoryTrend === 'stable' || stats.memoryTrend === 'unknown';
        if (!memoryStable) {
            warnings.push(`Memory usage is ${stats.memoryTrend}`);
        }
        return {
            initialLoadOk,
            subsequentLoadOk,
            memoryStable,
            warnings
        };
    }
}
// Global performance monitor instance
export const performanceMonitor = new PerformanceMonitor();
// Make it available globally for debugging
if (typeof window !== 'undefined') {
    (window as any).performanceMonitor = performanceMonitor;
}# Dockerfile para Frontend Web - Producción
FROM node:18-alpine AS builder

# Instalar dependencias del sistema
RUN apk add --no-cache libc6-compat

# Establecer directorio de trabajo
WORKDIR /app

# Copiar archivos de configuración
COPY package*.json ./
COPY next.config.ts ./
COPY tsconfig.json ./
COPY tailwind.config.ts ./
COPY postcss.config.mjs ./

# Instalar dependencias completas requeridas para compilar el proyecto
RUN npm ci && npm cache clean --force

# Copiar código fuente
COPY app/ ./app/
COPY components/ ./components/
COPY lib/ ./lib/
COPY contexts/ ./contexts/
COPY styles/ ./styles/
COPY public/ ./public/

# Compilar aplicación
ENV NEXT_TELEMETRY_DISABLED 1
RUN npm run build

# Etapa de producción
FROM node:18-alpine AS runner

# Crear usuario no-root
RUN addgroup --system --gid 1001 nodejs
RUN adduser --system --uid 1001 nextjs

# Establecer directorio de trabajo
WORKDIR /app

# Copiar archivos necesarios desde builder
COPY --from=builder /app/public ./public
COPY --from=builder --chown=nextjs:nodejs /app/.next/standalone ./
COPY --from=builder --chown=nextjs:nodejs /app/.next/static ./.next/static

# Cambiar a usuario no-root
USER nextjs

# Exponer puerto
EXPOSE 3000

# Variables de entorno
ENV NODE_ENV=production
ENV PORT=3000
ENV HOSTNAME="0.0.0.0"

# Health check
HEALTHCHECK --interval=30s --timeout=3s --start-period=5s --retries=3 \
    CMD node -e "require('http').get('http://localhost:3000/api/health', (res) => { process.exit(res.statusCode === 200 ? 0 : 1) })"

# Comando de inicio
